    24→/// Course metadata
    25→class CourseMetadata {
    26→  final String title;
    27→  final String description;
    28→  final CourseAuthor author;
    29→  final List<String> tags;
    30→  final String difficulty; // 'beginner' | 'intermediate' | 'advanced'
