    68→      title: json['title'] as String? ?? '',
    69→      description: json['description'] as String? ?? '',
    70→      author: CourseAuthor.fromJson(
    71→        json['author'] as Map<String, dynamic>? ?? {},
    72→      ),
    73→      tags:
    74→          (json['tags'] as List<dynamic>?)?.map((e) => e as String).toList() ??
    75→          [],
    76→      difficulty: json['difficulty'] as String? ?? 'beginner',
    77→      estimatedMinutes: json['estimatedMinutes'] as int? ?? 0,
    78→      createdAt: json['createdAt'] != null
