   152→/// Course model - matches PRD 5.1 JSON schema
   153→class Course {
   154→  static const String schemaVersion = '1.0.0';
   155→  static const String schemaUrl = 'https://primoria.com/course-schema/v1.json';
   156→
   157→  final String courseId;
   158→  final CourseMetadata metadata;
   159→  final CourseSettings settings;
   160→  final List<CourseLesson> lessons;
   161→
   162→  const Course({
   163→    required this.courseId,
   164→    required this.metadata,
   165→    required this.settings,
   166→    required this.lessons,
   167→  });
   168→
   169→  /// Create default new course
   170→  factory Course.create({String title = 'Untitled Course'}) {
   171→    return Course(
   172→      courseId: IdGenerator.courseId(),
   173→      metadata: CourseMetadata.create(title: title),
   174→      settings: const CourseSettings(),
   175→      lessons: [CourseLesson.create(title: 'Lesson 1')],
   176→    );
   177→  }
   178→
   179→  factory Course.fromJson(Map<String, dynamic> json) {
   180→    // backward compat: accept legacy 'pages' key
   181→    final lessonsRaw = (json['lessons'] ?? json['pages']) as List<dynamic>;
   182→    return Course(
   183→      courseId: json['courseId'] as String,
   184→      metadata: CourseMetadata.fromJson(
   185→        json['metadata'] as Map<String, dynamic>,
   186→      ),
   187→      settings: CourseSettings.fromJson(
   188→        json['settings'] as Map<String, dynamic>? ?? {},
   189→      ),
   190→      lessons: lessonsRaw
   191→          .map((e) => CourseLesson.fromJson(e as Map<String, dynamic>))
   192→          .toList(),
   193→    );
   194→  }
   195→
   196→  Map<String, dynamic> toJson() => {
   197→    '\$schema': schemaUrl,
   198→    'schemaVersion': schemaVersion,
   199→    'courseId': courseId,
   200→    'metadata': metadata.toJson(),
   201→    'settings': settings.toJson(),
   202→    'lessons': lessons.map((l) => l.toJson()).toList(),
   203→  };
   204→
   205→  Course copyWith({
   206→    String? courseId,
   207→    CourseMetadata? metadata,
   208→    CourseSettings? settings,
   209→    List<CourseLesson>? lessons,
   210→  }) {
   211→    return Course(
   212→      courseId: courseId ?? this.courseId,
   213→      metadata: metadata ?? this.metadata,
   214→      settings: settings ?? this.settings,
   215→      lessons: lessons ?? this.lessons,
   216→    );
   217→  }
   218→
   219→  /// Update metadata (auto-update updatedAt)
   220→  Course updateMetadata(CourseMetadata Function(CourseMetadata) update) {
   221→    final updatedMeta = update(metadata).copyWith(updatedAt: DateTime.now());
   222→    return copyWith(metadata: updatedMeta);
   223→  }
   224→
   225→  /// Add lesson
   226→  Course addLesson(CourseLesson lesson) {
   227→    return copyWith(lessons: [...lessons, lesson]);
   228→  }
   229→
   230→  /// Remove lesson
   231→  Course removeLesson(String lessonId) {
   232→    return copyWith(
   233→      lessons: lessons.where((l) => l.lessonId != lessonId).toList(),
   234→    );
   235→  }
   236→
   237→  /// Update lesson
   238→  Course updateLesson(CourseLesson updatedLesson) {
   239→    final updatedLessons = lessons.map((l) {
   240→      if (l.lessonId == updatedLesson.lessonId) return updatedLesson;
   241→      return l;
   242→    }).toList();
   243→    return copyWith(lessons: updatedLessons);
   244→  }
   245→
   246→  /// Get lesson
   247→  CourseLesson? getLesson(int index) {
   248→    if (index < 0 || index >= lessons.length) return null;
   249→    return lessons[index];
   250→  }
   251→
   252→  /// Find the first lesson/page pair that actually contains blocks.
   253→  ///
   254→  /// If [preferredLessonIndex] is provided and valid, it is used first. When
   255→  /// that lesson has no content, the search falls back to the rest of the
   256→  /// course. Returns `(0, 0)` when the course is empty or every page is empty.
   257→  (int, int) firstNonEmptyPageLocation({int? preferredLessonIndex}) {
   258→    if (lessons.isEmpty) return (0, 0);
   259→
   260→    if (preferredLessonIndex != null &&
   261→        preferredLessonIndex >= 0 &&
   262→        preferredLessonIndex < lessons.length) {
   263→      final preferredLesson = lessons[preferredLessonIndex];
   264→      if (preferredLesson.hasContent) {
   265→        return (preferredLessonIndex, preferredLesson.firstNonEmptyPageIndex);
   266→      }
   267→    }
   268→
   269→    for (int lessonIndex = 0; lessonIndex < lessons.length; lessonIndex++) {
   270→      final lesson = lessons[lessonIndex];
   271→      if (lesson.hasContent) {
   272→        return (lessonIndex, lesson.firstNonEmptyPageIndex);
   273→      }
   274→    }
   275→
   276→    if (preferredLessonIndex != null &&
   277→        preferredLessonIndex >= 0 &&
   278→        preferredLessonIndex < lessons.length) {
   279→      return (preferredLessonIndex, 0);
   280→    }
   281→
   282→    return (0, 0);
   283→  }
   284→}
