     5→/// Course lesson model — contains ordered pages, each holding blocks.
     6→class CourseLesson {
     7→  final String lessonId;
     8→  final String title;
     9→  final List<LessonPage> pages;
    10→
    11→  const CourseLesson({
    12→    required this.lessonId,
    13→    required this.title,
    14→    required this.pages,
    15→  });
    16→
    17→  /// Whether any page inside this lesson actually has blocks.
    18→  bool get hasContent => pages.any((page) => page.blocks.isNotEmpty);
    19→
    20→  /// Returns the first page index that contains blocks, or 0 if all are empty.
    21→  int get firstNonEmptyPageIndex {
    22→    final index = pages.indexWhere((page) => page.blocks.isNotEmpty);
    23→    return index >= 0 ? index : 0;
    24→  }
    25→
    26→  /// Create a lesson with one empty page.
    27→  factory CourseLesson.create({String title = 'New Lesson'}) {
    28→    return CourseLesson(
    29→      lessonId: IdGenerator.lessonId(),
    30→      title: title,
    31→      pages: [LessonPage.create(order: 0)],
    32→    );
    33→  }
    34→
    35→  factory CourseLesson.fromJson(Map<String, dynamic> json) {
    36→    final lessonId = (json['lessonId'] ?? json['pageId']) as String;
    37→    final title = json['title'] as String? ?? '';
    38→
    39→    // New format: has 'pages' key
    40→    if (json.containsKey('pages') && json['pages'] is List) {
    41→      final pages = (json['pages'] as List<dynamic>)
    42→          .map((e) => LessonPage.fromJson(e as Map<String, dynamic>))
    43→          .toList();
    44→      return CourseLesson(
    45→        lessonId: lessonId,
    46→        title: title,
    47→        pages: pages.isEmpty ? [LessonPage.create(order: 0)] : pages,
    48→      );
    49→    }
    50→
    51→    // Legacy format: has 'blocks' key → wrap into first page
    52→    final blocks =
    53→        (json['blocks'] as List<dynamic>?)
    54→            ?.map((e) => Block.fromJson(e as Map<String, dynamic>))
    55→            .toList() ??
    56→        [];
    57→    return CourseLesson(
    58→      lessonId: lessonId,
    59→      title: title,
    60→      pages: [
    61→        LessonPage(pageId: IdGenerator.pageId(), order: 0, blocks: blocks),
    62→      ],
    63→    );
    64→  }
    65→
    66→  Map<String, dynamic> toJson() => {
    67→    'lessonId': lessonId,
    68→    'title': title,
    69→    'pages': pages.map((p) => p.toJson()).toList(),
    70→  };
    71→
    72→  CourseLesson copyWith({
    73→    String? lessonId,
    74→    String? title,
    75→    List<LessonPage>? pages,
    76→  }) {
    77→    return CourseLesson(
    78→      lessonId: lessonId ?? this.lessonId,
    79→      title: title ?? this.title,
    80→      pages: pages ?? this.pages,
    81→    );
    82→  }
    83→
    84→  // ---------------------------------------------------------------------------
    85→  // Page-aware block operations
    86→  // ---------------------------------------------------------------------------
    87→
    88→  CourseLesson addBlock(Block block, {int pageIndex = 0}) {
    89→    if (pageIndex < 0 || pageIndex >= pages.length) return this;
    90→    final updated = [...pages];
    91→    updated[pageIndex] = pages[pageIndex].addBlock(block);
    92→    return copyWith(pages: updated);
    93→  }
    94→
    95→  CourseLesson removeBlock(String blockId, {int pageIndex = 0}) {
    96→    if (pageIndex < 0 || pageIndex >= pages.length) return this;
    97→    final updated = [...pages];
    98→    updated[pageIndex] = pages[pageIndex].removeBlock(blockId);
    99→    return copyWith(pages: updated);
   100→  }
   101→
   102→  CourseLesson updateBlock(Block updatedBlock, {int pageIndex = 0}) {
   103→    if (pageIndex < 0 || pageIndex >= pages.length) return this;
   104→    final updated = [...pages];
   105→    updated[pageIndex] = pages[pageIndex].updateBlock(updatedBlock);
   106→    return copyWith(pages: updated);
   107→  }
   108→
   109→  CourseLesson reorderBlocks(int oldIndex, int newIndex, {int pageIndex = 0}) {
   110→    if (pageIndex < 0 || pageIndex >= pages.length) return this;
   111→    final updated = [...pages];
   112→    updated[pageIndex] = pages[pageIndex].reorderBlocks(oldIndex, newIndex);
   113→    return copyWith(pages: updated);
   114→  }
   115→
   116→  // ---------------------------------------------------------------------------
   117→  // Page management
   118→  // ---------------------------------------------------------------------------
   119→
   120→  CourseLesson addPage() {
   121→    return copyWith(
   122→      pages: [
   123→        ...pages,
   124→        LessonPage.create(order: pages.length),
   125→      ],
   126→    );
   127→  }
   128→
   129→  CourseLesson removePage(int pageIndex) {
   130→    if (pages.length <= 1) return this;
   131→    if (pageIndex < 0 || pageIndex >= pages.length) return this;
   132→    final updated = [...pages]..removeAt(pageIndex);
   133→    final reordered = updated.asMap().entries.map((e) {
   134→      return e.value.copyWith(order: e.key);
   135→    }).toList();
   136→    return copyWith(pages: reordered);
   137→  }
   138→}
