     4→/// A single page within a lesson — holds an ordered list of blocks.
     5→class LessonPage {
     6→  final String pageId;
     7→  final int order;
     8→  final List<Block> blocks;
     9→
    10→  const LessonPage({
    11→    required this.pageId,
    12→    required this.order,
    13→    required this.blocks,
    14→  });
    15→
    16→  factory LessonPage.create({int order = 0}) {
    17→    return LessonPage(
    18→      pageId: IdGenerator.pageId(),
    19→      order: order,
    20→      blocks: [],
    21→    );
    22→  }
    23→
    24→  factory LessonPage.fromJson(Map<String, dynamic> json) {
    25→    return LessonPage(
    26→      pageId: json['pageId'] as String? ?? IdGenerator.pageId(),
    27→      order: json['order'] as int? ?? 0,
    28→      blocks: (json['blocks'] as List<dynamic>?)
    29→              ?.map((e) => Block.fromJson(e as Map<String, dynamic>))
    30→              .toList() ??
    31→          [],
    32→    );
    33→  }
    34→
    35→  Map<String, dynamic> toJson() => {
    36→        'pageId': pageId,
    37→        'order': order,
    38→        'blocks': blocks.map((b) => b.toJson()).toList(),
    39→      };
    40→
    41→  LessonPage copyWith({String? pageId, int? order, List<Block>? blocks}) {
    42→    return LessonPage(
    43→      pageId: pageId ?? this.pageId,
    44→      order: order ?? this.order,
    45→      blocks: blocks ?? this.blocks,
    46→    );
    47→  }
    48→
    49→  LessonPage addBlock(Block block) => copyWith(blocks: [...blocks, block]);
    50→
    51→  LessonPage removeBlock(String blockId) =>
    52→      copyWith(blocks: blocks.where((b) => b.id != blockId).toList());
    53→
    54→  LessonPage updateBlock(Block updated) => copyWith(
    55→        blocks: blocks.map((b) => b.id == updated.id ? updated : b).toList(),
    56→      );
    57→
    58→  LessonPage reorderBlocks(int oldIndex, int newIndex) {
    59→    final list = [...blocks];
    60→    final block = list.removeAt(oldIndex);
    61→    list.insert(newIndex, block);
    62→    final reordered = list.asMap().entries.map((e) {
    63→      return e.value.copyWith(
    64→        position: e.value.position.copyWith(order: e.key),
    65→      );
    66→    }).toList();
    67→    return copyWith(blocks: reordered);
    68→  }
    69→}
