   101→/// A formula descriptor for display
   102→class VisualFormula {
   103→  final String id;
   104→  final String expression; // e.g. 'PV = nRT'
   105→  final String? description;
   106→  final Map<String, String>? variableLabels; // e.g. {'P': 'Pressure', 'V': 'Volume'}
   107→
   108→  const VisualFormula({
   109→    required this.id,
   110→    required this.expression,
   111→    this.description,
   112→    this.variableLabels,
   113→  });
   114→
   115→  factory VisualFormula.fromJson(Map<String, dynamic> json) {
   116→    final rawLabels = json['variableLabels'];
   117→    return VisualFormula(
   118→      id: json['id'] as String? ?? '',
   119→      expression: json['expression'] as String? ?? '',
   120→      description: json['description'] as String?,
   121→      variableLabels:
