    64→/// User state management
    65→class UserProvider extends ChangeNotifier {
    66→  StorageService? _storage;
    67→  UserData? _user;
    68→  bool _isInitialized = false;
    69→  bool _isLoggedIn = false;
    70→  bool _isLoading = false;
    71→  String _errorMessage = '';
    72→  StreamSubscription<AuthState>? _authStateSub;
    73→
    74→  // Learning statistics (local cache, overridden by backend on sync)
    75→  int _streak = 0;
    76→  int _longestStreak = 0;
    77→  int _completedCourses = 0;
    78→  int _lessonsCompleted = 0;
    79→  int _totalStudyMinutes = 0;
    80→  int _completedQuestions = 0;
    81→  int _totalXp = 0;
    82→  List<String> _unlockedAchievements = [];
    83→
    84→  // Social counts (from backend)
    85→  int _followingCount = 0;
    86→  int _followersCount = 0;
    87→
    88→  // Getters
    89→  UserData? get user => _user;
    90→  bool get isInitialized => _isInitialized;
    91→  bool get isLoggedIn => _isLoggedIn;
    92→  bool get isParent => (_user?.role.trim().toLowerCase() ?? '') == 'parent';
    93→  bool get isLoading => _isLoading;
    94→  String get errorMessage => _errorMessage;
    95→  int get streak => _streak;
    96→  int get longestStreak => _longestStreak;
    97→  int get completedCourses => _completedCourses;
    98→  int get lessonsCompleted => _lessonsCompleted;
    99→  int get totalXp => _totalXp;
   100→  int get followingCount => _followingCount;
   101→  int get followersCount => _followersCount;
   102→  int get totalStudyMinutes => _totalStudyMinutes;
   103→  String get totalStudyTime {
   104→    final hours = _totalStudyMinutes ~/ 60;
   105→    if (hours > 0) {
   106→      return '${hours}h ${_totalStudyMinutes % 60}m';
   107→    }
   108→    return '${_totalStudyMinutes}m';
   109→  }
   110→
   111→  int get completedQuestions => _completedQuestions;
   112→  List<String> get unlockedAchievements => _unlockedAchievements;
   113→
   114→  Future<void> initialize() async {
   115→    _storage = await StorageService.getInstance();
   116→    _bindAuthState();
   117→    await _restoreSession();
   118→    if (_isLoggedIn) {
   119→      await _loadProfileFromBackend();
   120→    }
   121→    await _loadStats();
   122→    await _checkAndUpdateStreak();
   123→    _isInitialized = true;
   124→    notifyListeners();
   125→    // Non-blocking: refresh from backend after local init completes
   126→    if (_isLoggedIn) {
   127→      unawaited(_loadStatsFromBackend());
   128→    }
   129→  }
   130→
   131→  Future<void> _restoreSession() async {
   132→    final supabaseUser = SupabaseService.currentUser;
   133→    if (supabaseUser != null) {
   134→      _user = _userDataFromSupabase(supabaseUser);
   135→      await _storage?.saveUser(_user!.toJson());
   136→      _isLoggedIn = true;
   137→    } else {
   138→      _user = null;
   139→      final userData = _storage?.getUser();
   140→      if (userData != null) {
   141→        // Stale local cache but no Supabase session — clear it
   142→        await _storage?.clearUser();
   143→      }
   144→      _isLoggedIn = false;
   145→    }
   146→    notifyListeners();
   147→  }
   148→
   149→  void _bindAuthState() {
   150→    _authStateSub?.cancel();
   151→    _authStateSub = SupabaseService.authStateChanges.listen((state) async {
   152→      final supabaseUser = SupabaseService.currentUser;
   153→      if (supabaseUser == null) {
   154→        final changed = _isLoggedIn || _user != null;
   155→        _isLoggedIn = false;
   156→        _user = null;
   157→        await _storage?.clearUser();
   158→        if (changed) notifyListeners();
   159→        return;
   160→      }
   161→
   162→      final previousId = _user?.id;
   163→      _user = _userDataFromSupabase(supabaseUser);
   164→      _isLoggedIn = true;
   165→      await _storage?.saveUser(_user!.toJson());
   166→      notifyListeners();
   167→
   168→      // Keep profile fields (username/avatar/bio/cover) in sync after auth events.
   169→      if (state.event == AuthChangeEvent.signedIn ||
   170→          state.event == AuthChangeEvent.initialSession ||
   171→          state.event == AuthChangeEvent.userUpdated ||
   172→          previousId != _user!.id) {
   173→        unawaited(_loadProfileFromBackend());
   174→      }
   175→    });
   176→  }
   177→
   178→  UserData _userDataFromSupabase(dynamic supabaseUser) {
   179→    final meta = supabaseUser.userMetadata as Map<String, dynamic>? ?? {};
   180→    return UserData(
   181→      id: supabaseUser.id,
   182→      name:
   183→          (meta['name'] as String?) ??
