   103→
   104→  Color _parseColor(String? hex) {
   105→    if (hex == null) return AppColors.indigo;
   106→    try {
   107→      return Color(int.parse('FF${hex.replaceFirst('#', '')}', radix: 16));
   108→    } catch (_) {
   109→      return AppColors.indigo;
   110→    }
   111→  }
   112→
   113→  bool _isLessonLocked(Map<String, dynamic> lesson) {
   114→    final locked = lesson['is_locked'] == true;
   115→    if (!locked) return false;
   116→
   117→    final unlockType = (lesson['unlock_type'] as String? ?? 'none')
   118→        .trim()
   119→        .toLowerCase();
   120→    final prerequisiteId = lesson['prerequisite_lesson_id'] as String?;
   121→    final prerequisiteDone =
   122→        prerequisiteId != null && _completedLessonIds.contains(prerequisiteId);
   123→
   124→    switch (unlockType) {
   125→      case 'prerequisite':
   126→        return !prerequisiteDone;
   127→      case 'paid':
   128→        // Entitlement check will be integrated later.
   129→        return true;
   130→      case 'prerequisite_or_paid':
   131→        // Paid unlock not integrated yet; prerequisite path remains valid.
   132→        return !prerequisiteDone;
   133→      case 'prerequisite_and_paid':
   134→        // Paid unlock not integrated yet.
   135→        return true;
   136→      case 'none':
   137→      default:
   138→        return true;
   139→    }
   140→  }
   141→
   142→  String? _lockHintForLesson(Map<String, dynamic> lesson, AppLocalizations t) {
   143→    final unlockType = (lesson['unlock_type'] as String? ?? 'none')
   144→        .trim()
   145→        .toLowerCase();
   146→
   147→    switch (unlockType) {
   148→      case 'prerequisite':
   149→        return t.courseLockedPrerequisite;
   150→      case 'paid':
   151→        return t.courseLockedPaid;
   152→      case 'prerequisite_or_paid':
   153→        return t.courseLockedPrerequisiteOrPaid;
   154→      case 'prerequisite_and_paid':
   155→        return t.courseLockedPrerequisiteAndPaid;
   156→      default:
   157→        return t.courseLocked;
   158→    }
   159→  }
