   163→  Future<void> _enroll() async {
   164→    if (widget.courseId == null) return;
   165→    setState(() => _enrolling = true);
   166→    final ok = await SupabaseService.enrollInCourse(widget.courseId!);
   167→    if (!mounted) return;
   168→    setState(() => _enrolling = false);
   169→    if (ok) {
   170→      // Pop back to home screen, then notify HomeScreen to switch to home tab.
   171→      Navigator.pop(context);
   172→      widget.onEnrolled?.call();
   173→    }
   174→  }
