   178→  /// Returns the first unlocked, incomplete lesson across all chapters.
   179→  Map<String, dynamic>? get _nextLesson {
   180→    for (final chapter in _chapters) {
   181→      final lessons = (chapter['lessons'] as List? ?? [])
   182→          .cast<Map<String, dynamic>>();
   183→      for (final l in lessons) {
   184→        if (!_completedLessonIds.contains(l['id'] as String) &&
   185→            !_isLessonLocked(l)) {
   186→          return l;
   187→        }
   188→      }
   189→    }
   190→    return null;
