     8→  AchievementService._();
     9→
    10→  // ── Condition checkers ───────────────────────────────────────
    11→  // Each checker returns true if the slug should be awarded.
    12→
    13→  static bool _check(
    14→    String slug,
    15→    Map<String, dynamic> stats,
    16→    Map<String, dynamic> lessonResult,
    17→  ) {
    18→    final streak = (stats['current_streak'] as num?)?.toInt() ?? 0;
    19→    final lessonsCompleted = (stats['lessons_completed'] as num?)?.toInt() ?? 0;
    20→    final coursesCompleted = (stats['courses_completed'] as num?)?.toInt() ?? 0;
    21→    final accuracyPct = (lessonResult['accuracy_pct'] as num?)?.toInt() ?? 0;
    22→    final timeSpentSeconds =
    23→        (lessonResult['time_spent_seconds'] as num?)?.toInt() ?? 0;
    24→
    25→    switch (slug) {
    26→      // Streak
    27→      case 'streak_3':
    28→        return streak >= 3;
    29→      case 'streak_7':
    30→        return streak >= 7;
    31→      case 'streak_30':
    32→        return streak >= 30;
    33→      case 'streak_100':
    34→        return streak >= 100;
    35→      // Learning
    36→      case 'first_lesson':
    37→        return lessonsCompleted >= 1;
    38→      case 'first_course':
    39→        return coursesCompleted >= 1;
    40→      case 'courses_5':
    41→        return coursesCompleted >= 5;
    42→      case 'lessons_100':
    43→        return lessonsCompleted >= 100;
    44→      case 'courses_50':
    45→        return coursesCompleted >= 50;
    46→      // Challenge
    47→      case 'perfect_lesson':
    48→        return accuracyPct == 100;
    49→      case 'speed_lesson':
    50→        return timeSpentSeconds > 0 && timeSpentSeconds <= 900; // 15 min
    51→      // Social — checked separately via follow counts
    52→      default:
    53→        return false;
    54→    }
    55→  }
    56→
    57→  // ── Public API ───────────────────────────────────────────────
    58→
    59→  /// After a lesson is completed, check all applicable achievements.
    60→  /// Returns a list of newly unlocked [AchievementModel]s.
    61→  static Future<List<AchievementModel>> checkAndUnlock({
    62→    required Map<String, dynamic> rpcResult,
    63→    required int timeSpentSeconds,
    64→  }) async {
    65→    try {
    66→      // Fetch all achievements + earned state
    67→      final all = await SupabaseService.getAchievementsWithStatus();
    68→      final userStats = await SupabaseService.getUserStats() ?? {};
    69→      final lessonResult = {
    70→        ...rpcResult,
    71→        'time_spent_seconds': timeSpentSeconds,
    72→      };
    73→
    74→      final newlyUnlocked = <AchievementModel>[];
    75→
    76→      for (final row in all) {
    77→        final model = AchievementModel.fromMap(row);
    78→        if (model.isUnlocked) continue; // already earned
    79→        if (_check(model.slug, userStats, lessonResult)) {
    80→          await SupabaseService.unlockAchievement(model.id);
    81→          newlyUnlocked.add(
    82→            AchievementModel(
    83→              id: model.id,
    84→              slug: model.slug,
    85→              name: model.name,
    86→              description: model.description,
    87→              category: model.category,
    88→              rarity: model.rarity,
    89→              earnedAt: DateTime.now(),
    90→            ),
    91→          );
    92→        }
    93→      }
    94→
    95→      return newlyUnlocked;
    96→    } catch (e) {
    97→      debugPrint('[AchievementService] checkAndUnlock error: $e');
    98→      return [];
    99→    }
   100→  }
