   225→  /// Parse full course snapshot format:
   226→  /// {lessons: [{lessonId|pageId|id, title, blocks: [...]}, ...]}
   227→  /// and pick the lesson that matches the current lesson row.
   228→  List<_QuestionData> _parseBuilderLessons(
   229→    List<Map<String, dynamic>> lessons, {
   230→    String? currentLessonId,
   231→    String? currentLessonTitle,
   232→  }) {
   233→    if (lessons.isEmpty) return const [];
   234→
   235→    int targetIndex = -1;
   236→    final normalizedCurrentId = (currentLessonId ?? '').trim().toLowerCase();
   237→    final normalizedCurrentTitle = (currentLessonTitle ?? '')
   238→        .trim()
   239→        .toLowerCase();
   240→
   241→    if (normalizedCurrentId.isNotEmpty) {
   242→      targetIndex = lessons.indexWhere((lesson) {
   243→        final lessonId = _firstNonEmptyString([
   244→          lesson['lessonId'],
   245→          lesson['pageId'],
   246→          lesson['id'],
   247→        ]).toLowerCase();
   248→        return lessonId.isNotEmpty && lessonId == normalizedCurrentId;
   249→      });
   250→    }
   251→
   252→    if (targetIndex < 0 && normalizedCurrentTitle.isNotEmpty) {
   253→      targetIndex = lessons.indexWhere((lesson) {
   254→        final title = _firstNonEmptyString([lesson['title']]).toLowerCase();
   255→        return title.isNotEmpty && title == normalizedCurrentTitle;
   256→      });
   257→    }
   258→
   259→    final selected = lessons[targetIndex >= 0 ? targetIndex : 0];
   260→    final selectedTitle = _firstNonEmptyString([
   261→      selected['title'],
   262→      currentLessonTitle,
   263→      _i18n(en: 'Lesson', zh: '课程'),
   264→    ]);
   265→
   266→    // Prefer pages[] (current Course→Lessons→Pages→Blocks format)
   267→    if (selected['pages'] is List &&
   268→        (selected['pages'] as List).isNotEmpty) {
   269→      final pages = (selected['pages'] as List)
   270→          .whereType<Map>()
   271→          .map((p) => Map<String, dynamic>.from(p))
   272→          .toList();
   273→      return _parseBuilderPages(pages);
   274→    }
   275→
   276→    // Legacy fallback: lesson-level blocks[]
   277→    final blocks = (selected['blocks'] as List? ?? [])
   278→        .whereType<Map>()
   279→        .map((b) => Map<String, dynamic>.from(b))
   280→        .toList();
   281→    if (blocks.isEmpty) return const [];
   282→
   283→    return _parseBuilderPages([
   284→      {'title': selectedTitle, 'blocks': blocks},
   285→    ]);
   286→  }
