   386→            if (option is String && option.trim().isNotEmpty) {
   387→              options.add(option.trim());
   388→              optionIds.add(null);
   389→              continue;
   390→            }
   391→            if (option is Map) {
   392→              final map = Map<String, dynamic>.from(option);
   393→              final text = _firstNonEmptyString([
   394→                map['text'],
   395→                map['label'],
