   542→  static bool _isLessonContentEmpty(dynamic raw) {
   543→    if (raw == null) return true;
   544→    if (raw is String) {
   545→      final t = raw.trim();
   546→      return t.isEmpty || t == '{}' || t == '[]';
   547→    }
   548→    if (raw is List) return raw.isEmpty;
   549→    if (raw is Map) {
   550→      final map = Map<String, dynamic>.from(raw);
   551→      if (map.isEmpty) return true;
   552→      // Full course snapshot: non-empty only if lessons[] is non-empty
   553→      final lessons = map['lessons'];
   554→      if (lessons is List) return lessons.isEmpty;
   555→      // Per-lesson format: non-empty only if pages[] is non-empty
   556→      final pages = map['pages'];
   557→      if (pages is List) return pages.isEmpty;
   558→      // Legacy flat blocks at lesson level
   559→      final blocks = map['blocks'];
   560→      if (blocks is List) return blocks.isEmpty;
   561→      return false;
   562→    }
   563→    return false;
   564→  }
