   693→  /// Reconstruct a Course from individual lesson rows written by the agentic
   694→  /// generator. Each lesson row has content_json = {blocks: [...]}.
   695→  static Future<Course?> _reconstructCourseFromLessons(String courseId) async {
   696→    final courseRow = await client
   697→        .from('courses')
   698→        .select(
   699→          'id, title, description, difficulty_level, estimated_minutes, tags',
   700→        )
   701→        .eq('id', courseId)
   702→        .maybeSingle();
   703→    if (courseRow == null) return null;
   704→
   705→    final lessons = await client
   706→        .from('lessons')
   707→        .select('id, title, content_json, sort_key')
   708→        .eq('course_id', courseId)
   709→        .order('sort_key', ascending: true);
   710→
   711→    final lessonList = List<Map<String, dynamic>>.from(lessons as List);
   712→    // Accept lessons that carry either the new {pages:[...]} or legacy {blocks:[...]} format.
   713→    final agenticLessons = lessonList.where((l) {
   714→      final cj = l['content_json'];
   715→      if (cj is! Map) return false;
   716→      return cj.containsKey('pages') || cj.containsKey('blocks');
   717→    }).toList();
   718→
   719→    if (agenticLessons.isEmpty) return null;
   720→
   721→    final courseLessons = agenticLessons.map((l) {
   722→      final cj = Map<String, dynamic>.from(l['content_json'] as Map);
   723→      final lessonJson = <String, dynamic>{
   724→        'lessonId': l['id'] as String,
   725→        'title': l['title'] as String? ?? 'Untitled',
   726→      };
   727→      // Prefer pages (new multi-page format); fall back to blocks (legacy).
   728→      if (cj.containsKey('pages')) {
   729→        lessonJson['pages'] = cj['pages'];
   730→      } else {
   731→        lessonJson['blocks'] = cj['blocks'] ?? <dynamic>[];
   732→      }
   733→      return CourseLesson.fromJson(lessonJson);
   734→    }).toList();
   735→
   736→    final rawTags = courseRow['tags'];
   737→    final tags = rawTags is List
   738→        ? rawTags.map((e) => e.toString()).toList()
   739→        : <String>[];
   740→
   741→    return Course(
   742→      courseId: courseId,
   743→      metadata: CourseMetadata(
   744→        title: courseRow['title'] as String? ?? 'Untitled Course',
   745→        description: courseRow['description'] as String? ?? '',
   746→        author: const CourseAuthor(userId: 'ai', displayName: 'AI'),
   747→        tags: tags,
   748→        difficulty: _normalizeDifficulty(
   749→          courseRow['difficulty_level'] as String?,
   750→        ),
   751→        estimatedMinutes: courseRow['estimated_minutes'] as int? ?? 0,
   752→        createdAt: DateTime.now(),
   753→        updatedAt: DateTime.now(),
   754→        version: '1.0.0',
   755→      ),
   756→      settings: const CourseSettings(),
   757→      lessons: courseLessons,
   758→    );
   759→  }
