import 'block_type.dart';
import '../services/id_generator.dart';

part 'interactive_visual_content.dart';

/// Block position info
class BlockPosition {
  final int order;

  const BlockPosition({required this.order});

  factory BlockPosition.fromJson(Map<String, dynamic> json) {
    return BlockPosition(order: json['order'] as int? ?? 0);
  }

  Map<String, dynamic> toJson() => {'order': order};

  BlockPosition copyWith({int? order}) {
    return BlockPosition(order: order ?? this.order);
  }
}

/// Block style configuration
class BlockStyle {
  final String spacing;
  final String alignment;
  final double? height;
  final double? width;

  static const Set<String> _supportedSpacing = {'xs', 'sm', 'md', 'lg', 'xl'};
  static const Set<String> _supportedAlignment = {'left', 'center', 'right'};

  const BlockStyle({
    this.spacing = 'md',
    this.alignment = 'left',
    this.height,
    this.width,
  });

  factory BlockStyle.fromJson(Map<String, dynamic> json) {
    return BlockStyle(
      spacing: _normalizeSpacing(json['spacing'] as String?),
      alignment: _normalizeAlignment(json['alignment'] as String?),
      height: (json['height'] as num?)?.toDouble(),
      width: (json['width'] as num?)?.toDouble(),
    );
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{'spacing': spacing, 'alignment': alignment};
    if (height != null) map['height'] = height;
    if (width != null) map['width'] = width;
    return map;
  }

  BlockStyle copyWith({
    String? spacing,
    String? alignment,
    double? height,
    double? width,
    bool clearHeight = false,
    bool clearWidth = false,
  }) {
    return BlockStyle(
      spacing: _normalizeSpacing(spacing ?? this.spacing),
      alignment: _normalizeAlignment(alignment ?? this.alignment),
      height: clearHeight ? null : (height ?? this.height),
      width: clearWidth ? null : (width ?? this.width),
    );
  }

  static String _normalizeSpacing(String? spacing) {
    return _supportedSpacing.contains(spacing) ? spacing! : 'md';
  }

  static String _normalizeAlignment(String? alignment) {
    return _supportedAlignment.contains(alignment) ? alignment! : 'left';
  }
}

