  }

  /// Complete question
  Future<void> completeQuestion() async {
    await _storage?.incrementCompletedQuestions();
    _completedQuestions++;
    notifyListeners();
  }

  /// Complete course
  Future<void> completeCourse(String courseId) async {
    await _storage?.incrementCompletedCourses();
    _completedCourses++;
