  Widget _buildLessonNode({
    required String lessonId,
    required String lessonTitle,
    required bool isDone,
    required bool isNext,
    required bool isLocked,
    required String lockHint,
    required bool isLast,
    required AppLocalizations t,
  }) {
    final nodeColor = isDone
        ? AppColors.success
        : isLocked
        ? AppColors.surfaceVariant
        : isNext
        ? AppColors.primary
        : AppColors.surface;
    final nodeBorderColor = isDone
        ? AppColors.success
        : isLocked
        ? AppColors.border
        : isNext
        ? AppColors.primary
        : AppColors.border;

    void onTap() {
      if (isLocked) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(lockHint)));
        return;
      }
      Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => LessonScreen(
            lessonId: lessonId,
            lessonTitle: lessonTitle,
            gradient: _gradient,
          ),
        ),
      ).then((_) => _loadCourseData());
    }

    return IntrinsicHeight(
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Left: circle node + vertical connector
          SizedBox(
            width: 56,
            child: Column(
              children: [
                GestureDetector(
                  onTap: onTap,
                  child: Container(
                    width: 44,
                    height: 44,
                    decoration: BoxDecoration(
                      shape: BoxShape.circle,
                      color: nodeColor,
                      border: Border.all(
                        color: nodeBorderColor,
                        width: isNext ? 3 : 2,
                      ),
                      boxShadow: (isDone || isNext)
                          ? [
                              BoxShadow(
                                color: nodeBorderColor.withValues(alpha: 0.25),
                                blurRadius: 8,
                                offset: const Offset(0, 3),
                              ),
                            ]
                          : null,
                    ),
                    child: Center(
                      child: Icon(
                        isDone
                            ? Icons.check_rounded
                            : isLocked
                            ? Icons.lock_outline_rounded
                            : isNext
                            ? Icons.play_arrow_rounded
                            : Icons.radio_button_unchecked,
                        color: (isDone || isNext)
                            ? Colors.white
                            : isLocked
                            ? AppColors.textDisabled
                            : AppColors.textDisabled,
                        size: 22,
                      ),
                    ),
                  ),
                ),
                if (!isLast)
                  Expanded(
                    child: Container(
                      width: 3,
                      margin: const EdgeInsets.symmetric(vertical: 2),
                      decoration: BoxDecoration(
                        color: isDone
                            ? AppColors.success.withValues(alpha: 0.35)
                            : AppColors.border,
                        borderRadius: AppRadius.borderRadiusFull,
                      ),
                    ),
                  ),
              ],
            ),
          ),

          const SizedBox(width: 8),

          // Right: lesson card
          Expanded(
            child: Padding(
              padding: EdgeInsets.only(bottom: isLast ? 0 : AppSpacing.md),
              child: GestureDetector(
                onTap: onTap,
                child: Container(
                  padding: const EdgeInsets.all(AppSpacing.md),
                  decoration: BoxDecoration(
                    color: isLocked
                        ? AppColors.surfaceVariant
                        : isNext
                        ? AppColors.primary.withValues(alpha: 0.04)
                        : AppColors.surface,
                    borderRadius: AppRadius.borderRadiusXl,
                    border: isLocked
                        ? Border.all(color: AppColors.border)
                        : isNext
                        ? Border.all(
                            color: AppColors.primary.withValues(alpha: 0.35),
                            width: 1.5,
                          )
                        : Border.all(color: AppColors.border),
                    boxShadow: (isDone || isNext) && !isLocked
                        ? AppShadows.sm
                        : null,
                  ),
                  child: Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            if (isLocked) ...[
                              Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 6,
                                  vertical: 1,
                                ),
                                decoration: BoxDecoration(
                                  color: AppColors.textDisabled.withValues(
                                    alpha: 0.12,
                                  ),
                                  borderRadius: AppRadius.borderRadiusSm,
                                ),
                                child: Text(
                                  t.courseLocked,
                                  style: AppTypography.labelSmall.copyWith(
                                    color: AppColors.textSecondary,
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ),
                              const SizedBox(height: 4),
                            ] else if (isDone) ...[
                              Container(
                                padding: const EdgeInsets.symmetric(
                                  horizontal: 6,
                                  vertical: 1,
                                ),
                                decoration: BoxDecoration(
                                  color: AppColors.success.withValues(
