  Widget _avatarPreview({double size = 70}) {
    final url = _avatarUrlController.text.trim();
    final initial = _displayNameController.text.trim().isNotEmpty
        ? _displayNameController.text.trim()[0].toUpperCase()
        : (_email?.isNotEmpty == true ? _email![0].toUpperCase() : 'A');

    if (url.isEmpty) {
      return Container(
        width: size,
        height: size,
        decoration: BoxDecoration(
          color: AppColors.primary100,
          shape: BoxShape.circle,
          border: Border.all(color: AppColors.primary300),
        ),
        alignment: Alignment.center,
        child: Text(
          initial,
          style: TextStyle(
            fontSize: size * 0.34,
            fontWeight: FontWeight.w800,
            color: AppColors.primary700,
          ),
        ),
      );
    }

    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        border: Border.all(color: AppColors.primary300),
      ),
      clipBehavior: Clip.antiAlias,
      child: Image.network(
        url,
        fit: BoxFit.cover,
        errorBuilder: (_, __, ___) => Container(
          color: AppColors.primary100,
          alignment: Alignment.center,
          child: Text(
            initial,
            style: TextStyle(
              fontSize: size * 0.34,
              fontWeight: FontWeight.w800,
              color: AppColors.primary700,
            ),
          ),
        ),
      ),
    );
  }

