    return {'min': min, 'max': max};
  }
}

/// Feedback configuration
class Feedback {
  final String successMsg;
  final String? failMsg;
  final String? failMsgTooHigh;
  final String? failMsgTooLow;
  final String? hint;
  final String? explanation;

  const Feedback({
    required this.successMsg,
    this.failMsg,
    this.failMsgTooHigh,
    this.failMsgTooLow,
    this.hint,
    this.explanation,
  });

  factory Feedback.fromJson(Map<String, dynamic> json) {
    return Feedback(
      successMsg: json['success_msg'] as String,
      failMsg: json['fail_msg'] as String?,
      failMsgTooHigh: json['fail_msg_too_high'] as String?,
      failMsgTooLow: json['fail_msg_too_low'] as String?,
      hint: json['hint'] as String?,
      explanation: json['explanation'] as String?,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'success_msg': successMsg,
      'fail_msg': failMsg,
      'fail_msg_too_high': failMsgTooHigh,
      'fail_msg_too_low': failMsgTooLow,
      'hint': hint,
      'explanation': explanation,
    };
  }
}

/// Metadata
class Metadata {
  final String? createdAt;
  final String? updatedAt;
  final String? author;
  final List<String>? tags;

  const Metadata({this.createdAt, this.updatedAt, this.author, this.tags});

  factory Metadata.fromJson(Map<String, dynamic> json) {
    return Metadata(
      createdAt: json['created_at'] as String?,
      updatedAt: json['updated_at'] as String?,
      author: json['author'] as String?,
      tags: (json['tags'] as List<dynamic>?)?.map((e) => e as String).toList(),
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'created_at': createdAt,
      'updated_at': updatedAt,
      'author': author,
      'tags': tags,
    };
  }
}

