   323→  /// Register
   324→  Future<bool> register(String name, String email, String password) async {
   325→    _isLoading = true;
   326→    _errorMessage = '';
   327→    notifyListeners();
   328→
   329→    final result = await SupabaseService.signUp(
   330→      email: email,
