   334→
   335→    if (result.success && SupabaseService.currentUser != null) {
   336→      _user = _userDataFromSupabase(SupabaseService.currentUser!);
   337→      await _storage?.saveUser(_user!.toJson());
   338→      _isLoggedIn = true;
   339→      await _loadProfileFromBackend();
   340→    } else if (result.success) {
   341→      // Sign-up succeeded but no session yet (email confirmation required)
   342→      _errorMessage = 'Please check your email to confirm your account.';
   343→    } else {
   344→      _errorMessage = result.message;
   345→    }
   346→
   347→    _isLoading = false;
   348→    notifyListeners();
   349→    return result.success;
   350→  }
   351→
   352→  /// Logout
   353→  Future<void> logout() async {
   354→    await SupabaseService.signOut();
   355→    await _storage?.clearUser();
   356→    _user = null;
   357→    _isLoggedIn = false;
   358→    notifyListeners();
   359→  }
   360→
   361→  /// Reset password
   362→  Future<AuthResult> resetPassword(String email) async {
   363→    return SupabaseService.resetPassword(email: email);
   364→  }
   365→
   366→  /// Record study
   367→  Future<void> recordStudy(int minutes) async {
   368→    await _storage?.addStudyTime(minutes);
   369→    _totalStudyMinutes += minutes;
   370→
   371→    // Update learning streak
   372→    final lastStudyDate = _storage?.getLastStudyDate();
   373→    final now = DateTime.now();
   374→
   375→    if (lastStudyDate != null) {
   376→      final last = DateTime.parse(lastStudyDate);
   377→      final diff = now.difference(last).inDays;
   378→
   379→      if (diff >= 1) {
   380→        _streak++;
   381→        if (_streak > _longestStreak) {
   382→          _longestStreak = _streak;
   383→          await _storage?.saveLongestStreak(_longestStreak);
   384→        }
   385→      }
   386→    } else {
   387→      _streak = 1;
   388→    }
   389→
   390→    await _storage?.saveStreak(_streak);
   391→    await AudioService.getInstance().playStreak();
   392→
   393→    notifyListeners();
   394→  }
   395→
   396→  /// Complete course
   397→  Future<void> completeCourse(String courseId) async {
   398→    await _storage?.incrementCompletedCourses();
   399→    _completedCourses++;
   400→    notifyListeners();
   401→  }
   402→
   403→  /// Upgrade to Pro
   404→  Future<void> upgradeToPro() async {
   405→    if (_user != null) {
   406→      _user = UserData(
   407→        id: _user!.id,
   408→        name: _user!.name,
   409→        email: _user!.email,
   410→        avatarUrl: _user!.avatarUrl,
   411→        coverImageUrl: _user!.coverImageUrl,
   412→        bio: _user!.bio,
   413→        role: _user!.role,
   414→        isPro: true,
   415→        joinedAt: _user!.joinedAt,
   416→      );
   417→      await _storage?.saveUser(_user!.toJson());
   418→      notifyListeners();
   419→    }
   420→  }
   421→
   422→  @override
   423→  void dispose() {
   424→    _authStateSub?.cancel();
   425→    super.dispose();
   426→  }
   427→}
