          ],
        );
      case BlockType.functionFlow:
        return const FunctionFlowContent(
          title: 'Function Call Flow',
          nodes: [
            FunctionFlowNode(
              id: 'start',
              label: 'Start',
              x: 15,
              y: 50,
              kind: FunctionFlowNode.kindStart,
            ),
            FunctionFlowNode(
              id: 'process',
              label: 'processInput()',
              x: 50,
              y: 50,
              kind: FunctionFlowNode.kindFunction,
