            ),
            FunctionFlowNode(
              id: 'result',
              label: 'return result',
              x: 85,
              y: 50,
              kind: FunctionFlowNode.kindEnd,
            ),
          ],
          edges: [
            FunctionFlowEdge(from: 'start', to: 'process', label: 'call'),
            FunctionFlowEdge(from: 'process', to: 'result', label: 'return'),
          ],
          entryNodeId: 'start',
          steps: [
            FunctionFlowStep(edgeIndex: 0, note: 'Start calls processInput'),
            FunctionFlowStep(edgeIndex: 1, note: 'processInput returns result'),
          ],
        );
      case BlockType.multipleChoice:
        return MultipleChoiceContent(
          question: 'Enter a question',
          options: [
            const ChoiceOption(id: 'a', text: 'Option A'),
            const ChoiceOption(id: 'b', text: 'Option B'),
            const ChoiceOption(id: 'c', text: 'Option C'),
          ],
          correctAnswer: 'a',
          correctAnswers: ['a'],
        );
      case BlockType.fillBlank:
        return const FillBlankContent(
          question: 'Enter a fill-in-the-blank question',
        );
      case BlockType.trueFalse:
        return const TrueFalseContent(
          question: 'Enter a true or false statement',
          correctAnswer: true,
        );
      case BlockType.matching:
        return MatchingContent(
          question: 'Match the items on the left with those on the right',
          leftItems: const [
            MatchingItem(id: 'l1', text: 'Item 1'),
            MatchingItem(id: 'l2', text: 'Item 2'),
            MatchingItem(id: 'l3', text: 'Item 3'),
          ],
          rightItems: const [
            MatchingItem(id: 'r1', text: 'Match A'),
            MatchingItem(id: 'r2', text: 'Match B'),
            MatchingItem(id: 'r3', text: 'Match C'),
          ],
          correctPairs: const [
            MatchingPair(leftId: 'l1', rightId: 'r1'),
            MatchingPair(leftId: 'l2', rightId: 'r2'),
            MatchingPair(leftId: 'l3', rightId: 'r3'),
          ],
        );
      case BlockType.animation:
        return const AnimationContent();
      case BlockType.interactiveVisual:
        return const InteractiveVisualContent(
          mode: VisualMode.interactive,
          template: InteractiveVisualContent.templateGeneric,
          title: 'Interactive Visual',
        );
      case BlockType.video:
        return const VideoContent();
    }
  }

  factory Block.fromJson(Map<String, dynamic> json) {
    final type = BlockType.fromValue(json['type'] as String);
    final position = BlockPosition.fromJson(
      json['position'] as Map<String, dynamic>? ?? {},
    );
    return Block(
      id: json['id'] as String,
      type: type,
      position: position,
      style: BlockStyle.fromJson(json['style'] as Map<String, dynamic>? ?? {}),
      content: BlockContent.fromJson(
        type,
        json['content'] as Map<String, dynamic>,
      ),
      visibilityRule: _normalizeVisibilityRule(
        json['visibility_rule'] ?? json['visibilityRule'],
        order: position.order,
      ),
    );
  }

  Map<String, dynamic> toJson() => {
    'type': type.value,
    'id': id,
    'position': position.toJson(),
    'style': style.toJson(),
    'content': _normalizeToSnakeCase(content.toJson()),
    'visibility_rule': visibilityRule,
  };

  Block copyWith({
    String? id,
    BlockType? type,
    BlockPosition? position,
    BlockStyle? style,
    BlockContent? content,
    String? visibilityRule,
  }) {
    final nextPosition = position ?? this.position;
    return Block(
      id: id ?? this.id,
      type: type ?? this.type,
      position: nextPosition,
      style: style ?? this.style,
      content: content ?? this.content,
      visibilityRule: _normalizeVisibilityRule(
        visibilityRule ?? this.visibilityRule,
        order: nextPosition.order,
      ),
    );
  }

  static String _defaultVisibilityRuleForOrder(int order) {
    return order <= 0 ? alwaysVisible : afterPreviousCorrect;
  }

  static String _normalizeVisibilityRule(
    dynamic rawRule, {
    required int order,
  }) {
    final normalized = (rawRule is String ? rawRule : '').trim().toLowerCase();
    switch (normalized) {
      case alwaysVisible:
        return alwaysVisible;
      case 'afterpreviouscorrect':
      case 'after_previous_correct':
      case 'after-previous-correct':
        return afterPreviousCorrect;
      default:
        return _defaultVisibilityRuleForOrder(order);
    }
  }
}

