      map['initialVariables'] = initialVariables;
    }
    if (checkpoints.isNotEmpty) {
      map['checkpoints'] = checkpoints.map((cp) => cp.toJson()).toList();
    }
    return map;
  }

  CodeExecutionContent copyWith({
    String? title,
