  Map<String, dynamic> toJson() => {'id': id, 'text': text};

  MatchingItem copyWith({String? id, String? text}) {
    return MatchingItem(id: id ?? this.id, text: text ?? this.text);
  }
}

/// Matching question pair
class MatchingPair {
