    if (entryNodeId != null) map['entryNodeId'] = entryNodeId;
    return map;
  }

  FunctionFlowContent copyWith({
    String? title,
    List<FunctionFlowNode>? nodes,
    List<FunctionFlowEdge>? edges,
    String? entryNodeId,
    List<FunctionFlowStep>? steps,
    FunctionFlowStyle? style,
