  @override
  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{
      'title': title,
      'language': language,
      'sourceCode': sourceCode,
      'traceSteps': traceSteps.map((step) => step.toJson()).toList(),
      'controls': controls.toJson(),
