import 'block_type.dart';
import '../services/id_generator.dart';

part 'interactive_visual_content.dart';

// ── Key normalisation ─────────────────────────────────────────────────────────
// Builder stores content JSON in the database.  We output snake_case so that
// Viewer (and any future API consumer) can use a single, consistent key format.
// Builder's own fromJson() methods accept BOTH camelCase (legacy DB rows) and
// snake_case (new rows) so old course data continues to load correctly.

String _camelToSnake(String key) =>
    key.replaceAllMapped(RegExp(r'([A-Z])'), (m) => '_${m.group(0)!.toLowerCase()}');

Map<String, dynamic> _normalizeToSnakeCase(Map<String, dynamic> map) {
  return map.map((key, value) {
    final snakeKey = _camelToSnake(key);
    if (value is Map<String, dynamic>) {
      return MapEntry(snakeKey, _normalizeToSnakeCase(value));
    } else if (value is List) {
      return MapEntry(snakeKey, _normalizeListToSnakeCase(value));
    }
    return MapEntry(snakeKey, value);
  });
}

List<dynamic> _normalizeListToSnakeCase(List<dynamic> list) {
  return list.map((item) {
    if (item is Map<String, dynamic>) return _normalizeToSnakeCase(item);
    if (item is List) return _normalizeListToSnakeCase(item);
    return item;
  }).toList();
}

/// Block position info
class BlockPosition {
  final int order;

  const BlockPosition({required this.order});

  factory BlockPosition.fromJson(Map<String, dynamic> json) {
    return BlockPosition(order: json['order'] as int? ?? 0);
  }

  Map<String, dynamic> toJson() => {'order': order};

  BlockPosition copyWith({int? order}) {
    return BlockPosition(order: order ?? this.order);
  }
}

/// Block style configuration
class BlockStyle {
  final String spacing;
  final String alignment;
  final double? height;
  final double? width;

  static const Set<String> _supportedSpacing = {'xs', 'sm', 'md', 'lg', 'xl'};
  static const Set<String> _supportedAlignment = {'left', 'center', 'right'};

  const BlockStyle({
    this.spacing = 'md',
    this.alignment = 'left',
    this.height,
    this.width,
  });

  factory BlockStyle.fromJson(Map<String, dynamic> json) {
    return BlockStyle(
      spacing: _normalizeSpacing(json['spacing'] as String?),
      alignment: _normalizeAlignment(json['alignment'] as String?),
      height: (json['height'] as num?)?.toDouble(),
      width: (json['width'] as num?)?.toDouble(),
    );
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{'spacing': spacing, 'alignment': alignment};
    if (height != null) map['height'] = height;
    if (width != null) map['width'] = width;
    return map;
  }

  BlockStyle copyWith({
    String? spacing,
    String? alignment,
    double? height,
    double? width,
    bool clearHeight = false,
    bool clearWidth = false,
  }) {
    return BlockStyle(
      spacing: _normalizeSpacing(spacing ?? this.spacing),
      alignment: _normalizeAlignment(alignment ?? this.alignment),
      height: clearHeight ? null : (height ?? this.height),
      width: clearWidth ? null : (width ?? this.width),
    );
  }

  static String _normalizeSpacing(String? spacing) {
    return _supportedSpacing.contains(spacing) ? spacing! : 'md';
  }

  static String _normalizeAlignment(String? alignment) {
    return _supportedAlignment.contains(alignment) ? alignment! : 'left';
  }
}

/// Block content - base class
abstract class BlockContent {
  Map<String, dynamic> toJson();

  factory BlockContent.fromJson(BlockType type, Map<String, dynamic> json) {
    switch (type) {
      case BlockType.text:
        return TextContent.fromJson(json);
      case BlockType.image:
        return ImageContent.fromJson(json);
      case BlockType.codeBlock:
        return CodeBlockContent.fromJson(json);
      case BlockType.codePlayground:
        return CodePlaygroundContent.fromJson(json);
      case BlockType.codeExecution:
        return CodeExecutionContent.fromJson(json);
      case BlockType.functionFlow:
        return FunctionFlowContent.fromJson(json);
      case BlockType.multipleChoice:
        return MultipleChoiceContent.fromJson(json);
      case BlockType.fillBlank:
        return FillBlankContent.fromJson(json);
      case BlockType.trueFalse:
        return TrueFalseContent.fromJson(json);
      case BlockType.matching:
        return MatchingContent.fromJson(json);
      case BlockType.animation:
        return AnimationContent.fromJson(json);
      case BlockType.interactiveVisual:
        return InteractiveVisualContent.fromJson(json);
      case BlockType.video:
        return VideoContent.fromJson(json);
    }
  }
}

/// Text block content
class TextContent implements BlockContent {
  final String format; // 'richtext' | 'markdown' | 'plain' (last two for backwards compat)
  final String value;

  static const Set<String> _supportedFormats = {'richtext', 'markdown', 'plain'};

  const TextContent({this.format = 'richtext', this.value = ''});

  factory TextContent.fromJson(Map<String, dynamic> json) {
    final format = (json['format'] as String? ?? '').trim();
    return TextContent(
      format: _supportedFormats.contains(format) ? format : 'richtext',
      value: json['value'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toJson() => {'format': format, 'value': value};

  TextContent copyWith({String? format, String? value}) {
    final nextFormat = (format ?? this.format).trim();
    return TextContent(
      format: _supportedFormats.contains(nextFormat) ? nextFormat : 'richtext',
      value: value ?? this.value,
    );
  }
}

/// Image block content
class ImageContent implements BlockContent {
  final String url;
  final String? alt;
  final String? caption;

  const ImageContent({this.url = '', this.alt, this.caption});

  factory ImageContent.fromJson(Map<String, dynamic> json) {
    return ImageContent(
      url: json['url'] as String? ?? '',
      alt: json['alt'] as String?,
      caption: json['caption'] as String?,
    );
  }

  @override
  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{'url': url};
    if (alt != null) map['alt'] = alt;
    if (caption != null) map['caption'] = caption;
    return map;
  }
}

/// Code block content
class CodeBlockContent implements BlockContent {
  final String language;
  final String code;

  const CodeBlockContent({this.language = 'python', this.code = ''});

  factory CodeBlockContent.fromJson(Map<String, dynamic> json) {
    return CodeBlockContent(
      language: json['language'] as String? ?? 'python',
      code: json['code'] as String? ?? '',
    );
  }

  @override
  Map<String, dynamic> toJson() => {'language': language, 'code': code};
}

/// Code playground content
class CodePlaygroundContent implements BlockContent {
  final String language;
  final String initialCode;
  final String? expectedOutput;
  final List<String> hints;
  final bool runnable;

  const CodePlaygroundContent({
    this.language = 'python',
    this.initialCode = '',
    this.expectedOutput,
    this.hints = const [],
    this.runnable = true,
  });

  factory CodePlaygroundContent.fromJson(Map<String, dynamic> json) {
    return CodePlaygroundContent(
      language: json['language'] as String? ?? 'python',
      initialCode: (json['initial_code'] ?? json['initialCode']) as String? ?? '',
      expectedOutput: (json['expected_output'] ?? json['expectedOutput']) as String?,
      hints:
          (json['hints'] as List<dynamic>?)?.map((e) => e as String).toList() ??
          [],
      runnable: json['runnable'] as bool? ?? true,
    );
  }

  @override
  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{
      'language': language,
      'initialCode': initialCode,
      'runnable': runnable,
    };
    if (expectedOutput != null) map['expectedOutput'] = expectedOutput;
    if (hints.isNotEmpty) map['hints'] = hints;
    return map;
  }
}

/// Code execution trace step
class CodeExecutionTraceStep {
  final int line;
  final String? stdoutDelta;
  final Map<String, dynamic> variables;
  final List<String>? callStack;
  final String? note;

  const CodeExecutionTraceStep({
    required this.line,
    this.stdoutDelta,
    this.variables = const {},
    this.callStack,
    this.note,
  });

  factory CodeExecutionTraceStep.fromJson(Map<String, dynamic> json) {
    final rawLine = json['line'];
    final line = rawLine is num ? rawLine.toInt() : 1;

    final rawVariables = json['variables'];
    final variables = CodeExecutionContent._normalizeJsonMap(rawVariables);

    List<String>? callStack;
    final rawCallStack = json['call_stack'] ?? json['callStack'];
    if (rawCallStack is List) {
      final parsed = rawCallStack
          .map((value) => value.toString())
          .map((value) => value.trim())
          .where((value) => value.isNotEmpty)
          .toList();
      if (parsed.isNotEmpty) callStack = parsed;
    }

    final stdoutDelta = (json['stdout_delta'] ?? json['stdoutDelta']) as String?;
    final note = json['note'] as String?;

    return CodeExecutionTraceStep(
      line: line <= 0 ? 1 : line,
      stdoutDelta: stdoutDelta,
      variables: variables,
      callStack: callStack,
      note: note,
    );
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{'line': line, 'variables': variables};
    if (stdoutDelta != null) map['stdoutDelta'] = stdoutDelta;
    if (callStack != null) map['callStack'] = callStack;
    if (note != null) map['note'] = note;
    return map;
  }

  CodeExecutionTraceStep copyWith({
    int? line,
    String? stdoutDelta,
    Map<String, dynamic>? variables,
    List<String>? callStack,
    String? note,
    bool clearStdoutDelta = false,
    bool clearCallStack = false,
    bool clearNote = false,
  }) {
    return CodeExecutionTraceStep(
      line: (line ?? this.line) <= 0 ? 1 : (line ?? this.line),
      stdoutDelta: clearStdoutDelta ? null : (stdoutDelta ?? this.stdoutDelta),
      variables: variables ?? this.variables,
      callStack: clearCallStack ? null : (callStack ?? this.callStack),
      note: clearNote ? null : (note ?? this.note),
