          children: [
            // Left column
            Expanded(
              child: Column(
                children: leftItems
                    .map(
                      (item) => itemChip(
                        text: item,
                        isSelected: selectedLeft == item,
                        matchColor: _colorForLeftItem(item),
                        isLeft: true,
                        onTap: () => onLeftTap(item),
