   218→  /// Parse full course snapshot format:
   219→  /// {lessons: [{lessonId|pageId|id, title, blocks: [...]}, ...]}
   220→  /// and pick the lesson that matches the current lesson row.
   221→  List<_QuestionData> _parseBuilderLessons(
   222→    List<Map<String, dynamic>> lessons, {
   223→    String? currentLessonId,
   224→    String? currentLessonTitle,
   225→  }) {
   226→    if (lessons.isEmpty) return const [];
   227→
   228→    int targetIndex = -1;
   229→    final normalizedCurrentId = (currentLessonId ?? '').trim().toLowerCase();
   230→    final normalizedCurrentTitle = (currentLessonTitle ?? '')
   231→        .trim()
   232→        .toLowerCase();
   233→
   234→    if (normalizedCurrentId.isNotEmpty) {
   235→      targetIndex = lessons.indexWhere((lesson) {
   236→        final lessonId = _firstNonEmptyString([
   237→          lesson['lessonId'],
   238→          lesson['pageId'],
   239→          lesson['id'],
   240→        ]).toLowerCase();
   241→        return lessonId.isNotEmpty && lessonId == normalizedCurrentId;
   242→      });
   243→    }
   244→
   245→    if (targetIndex < 0 && normalizedCurrentTitle.isNotEmpty) {
   246→      targetIndex = lessons.indexWhere((lesson) {
   247→        final title = _firstNonEmptyString([lesson['title']]).toLowerCase();
   248→        return title.isNotEmpty && title == normalizedCurrentTitle;
   249→      });
   250→    }
   251→
   252→    final selected = lessons[targetIndex >= 0 ? targetIndex : 0];
   253→    final selectedTitle = _firstNonEmptyString([
   254→      selected['title'],
   255→      currentLessonTitle,
   256→      _i18n(en: 'Lesson', zh: '课程'),
   257→    ]);
   258→
   259→    // Prefer pages[] (current Course→Lessons→Pages→Blocks format)
   260→    if (selected['pages'] is List &&
   261→        (selected['pages'] as List).isNotEmpty) {
   262→      final pages = (selected['pages'] as List)
   263→          .whereType<Map>()
   264→          .map((p) => Map<String, dynamic>.from(p))
   265→          .toList();
   266→      return _parseBuilderPages(pages);
   267→    }
   268→
   269→    // Legacy fallback: lesson-level blocks[]
   270→    final blocks = (selected['blocks'] as List? ?? [])
   271→        .whereType<Map>()
   272→        .map((b) => Map<String, dynamic>.from(b))
   273→        .toList();
   274→    if (blocks.isEmpty) return const [];
   275→
   276→    return _parseBuilderPages([
   277→      {'title': selectedTitle, 'blocks': blocks},
   278→    ]);
   279→  }
