   281→  /// Parse DB list format: [{block_id, type, content, config, sort_key}]
   282→  List<_QuestionData> _parseDbBlocks(List<Map<String, dynamic>> blocks) {
   283→    blocks.sort(
   284→      (a, b) => ((a['sort_key'] as int?) ?? 0).compareTo(
   285→        (b['sort_key'] as int?) ?? 0,
   286→      ),
   287→    );
   288→
   289→    final questions = <_QuestionData>[];
   290→    for (final block in blocks) {
   291→      final type = block['type'] as String? ?? '';
   292→      final content = _toMap(block['content']);
   293→      final config = _toMap(block['config']);
   294→      questions.addAll(
   295→        _parseBlockItems(type: type, content: content, config: config, pageTitle: ''),
   296→      );
   297→    }
   298→    return questions;
   299→  }
