   301→  /// Parse Builder JSON map format: {pages: [{title, blocks: [{type, content}]}]}
   302→  List<_QuestionData> _parseBuilderPages(List<Map<String, dynamic>> pages) {
   303→    final questions = <_QuestionData>[];
   304→
   305→    for (final page in pages) {
   306→      final pageTitle = page['title'] as String? ?? '';
   307→      final blocks = (page['blocks'] as List? ?? [])
   308→          .whereType<Map>()
   309→          .map((b) => Map<String, dynamic>.from(b))
   310→          .toList();
   311→
   312→      for (final block in blocks) {
   313→        final type = block['type'] as String? ?? '';
   314→        final content = _toMap(block['content']);
   315→        final rule = (block['visibility_rule'] as String? ??
   316→                block['visibilityRule'] as String? ??
   317→                'always')
   318→            .trim();
   319→        final items = _parseBlockItems(
   320→          type: type,
   321→          content: content,
   322→          config: const {},
   323→          pageTitle: pageTitle,
   324→        );
   325→        questions.addAll(_withVisibilityRule(items, rule));
   326→      }
   327→    }
   328→
   329→    return questions;
   330→  }
