   332→  /// Applies [rule] to the first item in [items] (subsequent items from
   333→  /// multi-block expansions always remain 'always').
   334→  List<_QuestionData> _withVisibilityRule(
   335→    List<_QuestionData> items,
   336→    String rule,
   337→  ) {
   338→    if (items.isEmpty || rule == 'always') return items;
   339→    final first = items.first;
   340→    final updated = _QuestionData(
   341→      type: first.type,
   342→      title: first.title,
   343→      content: first.content,
   344→      options: first.options,
