   443→  /// Renders a function-flow block as:
   444→  ///   1. An info card listing node labels and descriptions.
   445→  ///   2. One info card per step that has a note.
   446→  List<_QuestionData> _parseFunctionFlow(
   447→    Map<String, dynamic> content,
   448→    String pageTitle,
   449→  ) {
   450→    final title = _firstNonEmptyString([
   451→      content['title'],
   452→      pageTitle,
   453→      _i18n(en: 'Function Flow', zh: '函数流程'),
   454→    ]);
   455→
   456→    final nodes = (content['nodes'] as List? ?? []).whereType<Map>();
   457→    final steps = (content['steps'] as List? ?? []).whereType<Map>();
   458→
   459→    final nodeLines = nodes
   460→        .where((n) {
   461→          final label = (n['label'] as String? ?? '').trim();
   462→          return label.isNotEmpty;
   463→        })
   464→        .map((n) {
   465→          final label = (n['label'] as String? ?? '').trim();
   466→          final desc = (n['description'] as String? ?? '').trim();
   467→          return desc.isNotEmpty ? '• $label: $desc' : '• $label';
   468→        })
   469→        .join('\n');
   470→
   471→    final results = <_QuestionData>[
   472→      _QuestionData(
   473→        type: QuestionType.info,
   474→        title: title,
   475→        content: nodeLines,
   476→      ),
   477→    ];
   478→
   479→    var stepNum = 1;
   480→    for (final step in steps) {
   481→      final note = (step['note'] as String? ?? '').trim();
   482→      if (note.isEmpty) continue;
   483→      results.add(_QuestionData(
   484→        type: QuestionType.info,
   485→        title: _i18n(en: 'Step $stepNum', zh: '步骤 $stepNum'),
   486→        content: note,
   487→      ));
   488→      stepNum++;
   489→    }
   490→
   491→    return results;
   492→  }
