   937→  static int _computeCurrentStreak(Set<DateTime> activeDayKeys) {
   938→    if (activeDayKeys.isEmpty) return 0;
   939→    final now = DateTime.now().toLocal();
   940→    final today = DateTime.utc(now.year, now.month, now.day);
   941→    DateTime cursor = today;
   942→
   943→    // Keep streak if user studied yesterday but not yet today.
   944→    if (!activeDayKeys.contains(cursor)) {
   945→      final yesterday = cursor.subtract(const Duration(days: 1));
   946→      if (!activeDayKeys.contains(yesterday)) return 0;
   947→      cursor = yesterday;
   948→    }
   949→
   950→    var streak = 0;
   951→    while (activeDayKeys.contains(cursor)) {
   952→      streak++;
   953→      cursor = cursor.subtract(const Duration(days: 1));
   954→    }
   955→    return streak;
   956→  }
