   958→  static int _computeLongestStreak(Set<DateTime> activeDayKeys) {
   959→    if (activeDayKeys.isEmpty) return 0;
   960→    final sorted = activeDayKeys.toList()..sort();
   961→    var longest = 1;
   962→    var current = 1;
   963→    for (var i = 1; i < sorted.length; i++) {
   964→      final diff = sorted[i].difference(sorted[i - 1]).inDays;
   965→      if (diff == 1) {
   966→        current++;
   967→        if (current > longest) longest = current;
   968→      } else {
   969→        current = 1;
   970→      }
   971→    }
   972→    return longest;
   973→  }
