  final int estimatedMinutes;
  final DateTime createdAt;
  final DateTime updatedAt;
  final String version;

  const CourseMetadata({
    required this.title,
    required this.description,
    required this.author,
    required this.tags,
    required this.difficulty,
    required this.estimatedMinutes,
    required this.createdAt,
    required this.updatedAt,
    required this.version,
  });

  factory CourseMetadata.create({
    String title = 'Untitled Course',
    String description = '',
  }) {
    final now = DateTime.now();
    return CourseMetadata(
      title: title,
      description: description,
      author: const CourseAuthor(userId: 'local', displayName: 'Local user'),
      tags: [],
      difficulty: 'beginner',
      estimatedMinutes: 0,
      createdAt: now,
      updatedAt: now,
      version: '1.0.0',
    );
  }

  factory CourseMetadata.fromJson(Map<String, dynamic> json) {
    return CourseMetadata(
      title: json['title'] as String? ?? '',
      description: json['description'] as String? ?? '',
      author: CourseAuthor.fromJson(
        json['author'] as Map<String, dynamic>? ?? {},
      ),
      tags:
          (json['tags'] as List<dynamic>?)?.map((e) => e as String).toList() ??
          [],
      difficulty: json['difficulty_level'] as String? ?? json['difficulty'] as String? ?? 'beginner',
      estimatedMinutes: json['estimatedMinutes'] as int? ?? 0,
      createdAt: json['createdAt'] != null
          ? DateTime.parse(json['createdAt'] as String)
          : DateTime.now(),
      updatedAt: json['updatedAt'] != null
          ? DateTime.parse(json['updatedAt'] as String)
          : DateTime.now(),
      version: json['version'] as String? ?? '1.0.0',
    );
  }

  Map<String, dynamic> toJson() => {
    'title': title,
    'description': description,
    'author': author.toJson(),
    'tags': tags,
    'difficulty': difficulty,
    'estimatedMinutes': estimatedMinutes,
    'createdAt': createdAt.toIso8601String(),
    'updatedAt': updatedAt.toIso8601String(),
    'version': version,
  };

  CourseMetadata copyWith({
    String? title,
    String? description,
    CourseAuthor? author,
    List<String>? tags,
    String? difficulty,
    int? estimatedMinutes,
    DateTime? createdAt,
    DateTime? updatedAt,
    String? version,
  }) {
    return CourseMetadata(
      title: title ?? this.title,
      description: description ?? this.description,
      author: author ?? this.author,
      tags: tags ?? this.tags,
      difficulty: difficulty ?? this.difficulty,
      estimatedMinutes: estimatedMinutes ?? this.estimatedMinutes,
      createdAt: createdAt ?? this.createdAt,
      updatedAt: updatedAt ?? this.updatedAt,
      version: version ?? this.version,
    );
  }
}

/// Course settings
class CourseSettings {
  final String theme; // 'light' | 'dark'
  final String primaryColor;
  final String fontFamily;

  const CourseSettings({
    this.theme = 'light',
    this.primaryColor = 'blue',
    this.fontFamily = 'system',
  });

  factory CourseSettings.fromJson(Map<String, dynamic> json) {
