            ],
          ),
        );
      default:
        // Generic: show state key-values
        return Container(
          color: bg,
          padding: const EdgeInsets.all(12),
          child:
              _state.isEmpty
                  ? Center(
                    child: Text(
                      widget.title,
                      style: TextStyle(
                        fontSize: 15,
                        color:
                            isDark
                                ? const Color(0xFFE6EDF3)
                                : const Color(0xFF1F2328),
                      ),
                    ),
                  )
                  : Wrap(
                    spacing: 16,
                    runSpacing: 8,
                    children:
                        _state.entries
                            .map(
                              (e) => Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    e.key,
                                    style: TextStyle(
                                      fontSize: 10,
                                      color:
                                          isDark
                                              ? const Color(0xFF8B949E)
                                              : const Color(0xFF57606A),
                                    ),
                                  ),
                                  Text(
                                    e.value.toString(),
                                    style: TextStyle(
                                      fontSize: 16,
                                      fontWeight: FontWeight.w700,
                                      color:
                                          isDark
                                              ? const Color(0xFF58A6FF)
                                              : const Color(0xFF0969DA),
                                    ),
                                  ),
                                ],
