import 'dart:convert';
import 'dart:math' as math;

import 'package:flutter/material.dart';
import 'package:flutter_markdown/flutter_markdown.dart';
import 'package:confetti/confetti.dart';
import 'package:provider/provider.dart';
import '../theme/theme.dart';
import '../components/feedback/feedback_dialog.dart';
import '../providers/user_provider.dart';
import '../providers/language_provider.dart';
import '../l10n/app_localizations.dart';
import '../services/audio_service.dart';
import '../services/supabase_service.dart';
import 'lesson_result_screen.dart';

/// Lesson/Interactive learning page - Duolingo + Brilliant style
class LessonScreen extends StatefulWidget {
  final String? lessonId;
  final String? lessonTitle;
  final LinearGradient? gradient;

  const LessonScreen({
    super.key,
    this.lessonId,
    this.lessonTitle,
    this.gradient,
  });

  @override
  State<LessonScreen> createState() => _LessonScreenState();
}

class _LessonScreenState extends State<LessonScreen> {
  // ── Loading state ─────────────────────────────────────────────
  bool _loadingLesson = true;
  bool _contentUnavailable = false;
  String? _resolvedLessonTitle;

  // ── Question state ────────────────────────────────────────────
  List<_QuestionData> _questions = [];
  int _currentIndex = 0;
  String? _selectedOption;
  final _inputController = TextEditingController();
  List<String> _sortingOrder = [];

  // ── Matching state ────────────────────────────────────────────
  String? _selectedLeftItem;
  Map<String, String> _matchingState = {}; // left item → right item

  // ── Multi-choice state ────────────────────────────────────────
  Set<int> _multiChoiceSelection = {};

  // ── Hint state ────────────────────────────────────────────────
  int _hintsUsed = 0;
  bool _hintVisible = false;

  // ── Transition key (AnimatedSwitcher) ─────────────────────────
  int _questionAnimKey = 0;

  // ── Answer tracking ───────────────────────────────────────────
  int _correctCount = 0;
  int _totalCount = 0;
  // Tracks whether the most recent interactive question was answered correctly.
  // Used to enforce afterPreviousCorrect visibility gates.
  bool _lastAnsweredCorrectly = true;

  // ── Supporting services ───────────────────────────────────────
  late ConfettiController _confettiController;
  final _audioService = AudioService.getInstance();
  final DateTime _startTime = DateTime.now();

  String _title(AppLocalizations t) {
    final title = _firstNonEmptyString([
      _resolvedLessonTitle,
      widget.lessonTitle,
    ]);
    return title.isNotEmpty ? title : t.lessonDefaultTitle;
  }

  AppLocalizations get _t => context.read<LanguageProvider>().t;

  String _i18n({required String en, required String zh}) {
    return _t.isZh ? zh : en;
  }

  // ── Lifecycle ─────────────────────────────────────────────────

  @override
  void initState() {
    super.initState();
    _confettiController = ConfettiController(
      duration: const Duration(seconds: 3),
    );
    _initLesson();
  }

  @override
  void dispose() {
    _inputController.dispose();
    _confettiController.dispose();
    super.dispose();
  }

  Future<void> _initLesson() async {
    final lessonId = widget.lessonId;
    List<_QuestionData> questions = [];
    String resolvedLessonTitle = '';

    try {
      if (lessonId != null && lessonId != 'daily') {
        final content = await SupabaseService.getLessonContent(lessonId);
        if (content != null) {
          resolvedLessonTitle = _firstNonEmptyString([content['title']]);
          questions = _parseContentJson(content);
        }
        if (questions.isEmpty) {
          _contentUnavailable = true;
          questions = _contentUnavailableQuestions();
        }
      } else {
        questions = _demoQuestions();
      }
    } catch (_) {
      if (lessonId != null && lessonId != 'daily') {
        _contentUnavailable = true;
        questions = _contentUnavailableQuestions();
      } else {
        questions = _demoQuestions();
      }
    }

    if (!mounted) return;
    setState(() {
      _resolvedLessonTitle = _firstNonEmptyString([
        _resolvedLessonTitle,
        resolvedLessonTitle,
      ]);
      _questions = questions;
      _loadingLesson = false;
      // Init sorting order from first sorting question
      for (final q in questions) {
        if (q.type == QuestionType.sorting && q.sortingItems != null) {
          _sortingOrder = List.from(q.sortingItems!);
          break;
        }
      }
    });
  }

  // ── Content JSON parser ───────────────────────────────────────

  /// Detects content_json format and delegates to the appropriate parser.
  /// Handles two formats:
  ///   1. DB list format: [{block_id, type, content, config, sort_key}]
  ///   2. Builder JSON map format: {pages|lessons|blocks: ...}
  List<_QuestionData> _parseContentJson(Map<String, dynamic> lesson) {
    dynamic raw = lesson['content_json'];
    if (raw == null) return [];

    List<_QuestionData> questions;
    try {
      if (raw is String && raw.trim().isNotEmpty) {
        raw = jsonDecode(raw);
      }

      if (raw is List) {
        questions = _parseDbBlocks(
          raw.whereType<Map>().cast<Map<String, dynamic>>().toList(),
        );
      } else if (raw is Map) {
        final map = Map<String, dynamic>.from(raw);
        final lessons = map['lessons'];
        final pages = map['pages'];

        if (lessons is List && lessons.isNotEmpty) {
          questions = _parseBuilderLessons(
            lessons.whereType<Map>().cast<Map<String, dynamic>>().toList(),
            currentLessonId: lesson['id']?.toString(),
            currentLessonTitle: lesson['title']?.toString(),
          );
        } else if (pages is List && pages.isNotEmpty) {
          questions = _parseBuilderPages(
            pages.whereType<Map>().cast<Map<String, dynamic>>().toList(),
          );
        } else if (map['blocks'] is List) {
          questions = _parseBuilderPages([
            {
              'title': lesson['title'] ?? _i18n(en: 'Lesson', zh: '课程'),
              'blocks': map['blocks'],
            },
          ]);
        } else {
          questions = [];
        }
      } else {
        questions = [];
      }
    } catch (_) {
      questions = [];
    }

    if (questions.isEmpty) return [];

    // Always append a completion card
    questions.add(
      _QuestionData(
        type: QuestionType.info,
        title: _i18n(en: 'Lesson Complete!', zh: '课程完成！'),
        content: _i18n(
          en: 'Great job! You\'ve finished this lesson.\n\nKeep learning every day!',
          zh: '做得很棒！你已完成本节课程。\n\n坚持每天学习，进步会更快！',
        ),
        isLast: true,
      ),
    );

    return questions;
  }

  /// Parse full course snapshot format:
  /// {lessons: [{lessonId|pageId|id, title, blocks: [...]}, ...]}
  /// and pick the lesson that matches the current lesson row.
  List<_QuestionData> _parseBuilderLessons(
    List<Map<String, dynamic>> lessons, {
    String? currentLessonId,
    String? currentLessonTitle,
  }) {
    if (lessons.isEmpty) return const [];

    int targetIndex = -1;
    final normalizedCurrentId = (currentLessonId ?? '').trim().toLowerCase();
    final normalizedCurrentTitle = (currentLessonTitle ?? '')
        .trim()
        .toLowerCase();

    if (normalizedCurrentId.isNotEmpty) {
      targetIndex = lessons.indexWhere((lesson) {
        final lessonId = _firstNonEmptyString([
          lesson['lessonId'],
          lesson['pageId'],
          lesson['id'],
        ]).toLowerCase();
        return lessonId.isNotEmpty && lessonId == normalizedCurrentId;
      });
    }

    if (targetIndex < 0 && normalizedCurrentTitle.isNotEmpty) {
      targetIndex = lessons.indexWhere((lesson) {
        final title = _firstNonEmptyString([lesson['title']]).toLowerCase();
        return title.isNotEmpty && title == normalizedCurrentTitle;
      });
    }

    final selected = lessons[targetIndex >= 0 ? targetIndex : 0];
    final selectedTitle = _firstNonEmptyString([
      selected['title'],
      currentLessonTitle,
      _i18n(en: 'Lesson', zh: '课程'),
    ]);

    // Prefer pages[] (current Course→Lessons→Pages→Blocks format)
    if (selected['pages'] is List &&
        (selected['pages'] as List).isNotEmpty) {
      final pages = (selected['pages'] as List)
          .whereType<Map>()
          .map((p) => Map<String, dynamic>.from(p))
          .toList();
      return _parseBuilderPages(pages);
    }

    // Legacy fallback: lesson-level blocks[]
    final blocks = (selected['blocks'] as List? ?? [])
        .whereType<Map>()
        .map((b) => Map<String, dynamic>.from(b))
        .toList();
    if (blocks.isEmpty) return const [];

    return _parseBuilderPages([
      {'title': selectedTitle, 'blocks': blocks},
    ]);
  }

  /// Parse DB list format: [{block_id, type, content, config, sort_key}]
  List<_QuestionData> _parseDbBlocks(List<Map<String, dynamic>> blocks) {
    blocks.sort(
      (a, b) => ((a['sort_key'] as int?) ?? 0).compareTo(
        (b['sort_key'] as int?) ?? 0,
      ),
    );

    final questions = <_QuestionData>[];
    for (final block in blocks) {
      final type = block['type'] as String? ?? '';
      final content = _toMap(block['content']);
      final config = _toMap(block['config']);
      questions.addAll(
        _parseBlockItems(type: type, content: content, config: config, pageTitle: ''),
      );
    }
    return questions;
  }

  /// Parse Builder JSON map format: {pages: [{title, blocks: [{type, content}]}]}
  List<_QuestionData> _parseBuilderPages(List<Map<String, dynamic>> pages) {
    final questions = <_QuestionData>[];

    for (final page in pages) {
      final pageTitle = page['title'] as String? ?? '';
      final blocks = (page['blocks'] as List? ?? [])
          .whereType<Map>()
          .map((b) => Map<String, dynamic>.from(b))
          .toList();

      for (final block in blocks) {
        final type = block['type'] as String? ?? '';
        final content = _toMap(block['content']);
        final rule = (block['visibility_rule'] as String? ??
                block['visibilityRule'] as String? ??
                'always')
            .trim();
        final items = _parseBlockItems(
          type: type,
          content: content,
          config: const {},
          pageTitle: pageTitle,
        );
        questions.addAll(_withVisibilityRule(items, rule));
      }
    }

    return questions;
  }

  /// Applies [rule] to the first item in [items] (subsequent items from
  /// multi-block expansions always remain 'always').
  List<_QuestionData> _withVisibilityRule(
    List<_QuestionData> items,
    String rule,
  ) {
    if (items.isEmpty || rule == 'always') return items;
    final first = items.first;
    final updated = _QuestionData(
      type: first.type,
      title: first.title,
      content: first.content,
      options: first.options,
      correctIndex: first.correctIndex,
      correctAnswer: first.correctAnswer,
      sortingItems: first.sortingItems,
      correctOrder: first.correctOrder,
      successMsg: first.successMsg,
      failMsg: first.failMsg,
      isLast: first.isLast,
      matchingLeftItems: first.matchingLeftItems,
      matchingRightItems: first.matchingRightItems,
      matchingCorrectPairs: first.matchingCorrectPairs,
      hints: first.hints,
      imageUrl: first.imageUrl,
      visualSpec: first.visualSpec,
      visibilityRule: rule,
      correctIndices: first.correctIndices,
    );
    return [updated, ...items.skip(1)];
  }

  /// Wrapper that returns 0-N questions per block.
  /// Most types produce 1 item via [_parseBlock]; code-execution and
  /// function-flow expand into an intro card + interactive questions.
  List<_QuestionData> _parseBlockItems({
    required String type,
    required Map<String, dynamic> content,
    required Map<String, dynamic> config,
    required String pageTitle,
  }) {
    final normalizedType = type.trim().toLowerCase().replaceAll('_', '-');

    if (normalizedType == 'code-execution') {
      return _parseCodeExecution(content, pageTitle);
    }
    if (normalizedType == 'function-flow') {
      return _parseFunctionFlow(content, pageTitle);
    }

    final single = _parseBlock(
      type: type,
      content: content,
      config: config,
      pageTitle: pageTitle,
    );
    return single == null ? const [] : [single];
  }

  /// Renders a code-execution block as:
  ///   1. An info card showing the source code.
  ///   2. One multiple-choice card per checkpoint question.
  List<_QuestionData> _parseCodeExecution(
    Map<String, dynamic> content,
    String pageTitle,
  ) {
    final sourceCode =
        content['source_code'] as String? ??
        content['sourceCode'] as String? ??
        content['code'] as String? ??
        '';
    final language = content['language'] as String? ?? 'python';
    final title = _firstNonEmptyString([
      content['title'],
      pageTitle,
      _i18n(en: 'Code Execution', zh: '代码执行'),
    ]);

    final results = <_QuestionData>[];

    if (sourceCode.isNotEmpty) {
      results.add(_QuestionData(
        type: QuestionType.info,
        title: title,
        content: '```$language\n$sourceCode\n```',
      ));
    }

    final checkpoints = (content['checkpoints'] as List? ?? []).whereType<Map>();
    for (final cp in checkpoints) {
      final question = (cp['question'] as String? ?? '').trim();
      final options = (cp['options'] as List? ?? [])
          .whereType<String>()
          .where((s) => s.isNotEmpty)
          .toList();
      final correctIndex =
          cp['correctIndex'] is num ? (cp['correctIndex'] as num).toInt() : 0;
      if (question.isEmpty || options.length < 2) continue;
      results.add(_QuestionData(
        type: QuestionType.choice,
        title: question,
        content: '',
        options: options,
        correctIndex: correctIndex,
        successMsg: _firstNonEmptyString([
          cp['explanation'],
          _i18n(en: 'Correct!', zh: '正确！'),
        ]),
        failMsg: _i18n(en: 'Not quite — try again.', zh: '不对，再试一次。'),
      ));
    }

    return results;
  }

  /// Renders a function-flow block as:
  ///   1. An info card listing node labels and descriptions.
  ///   2. One info card per step that has a note.
  List<_QuestionData> _parseFunctionFlow(
    Map<String, dynamic> content,
    String pageTitle,
  ) {
    final title = _firstNonEmptyString([
      content['title'],
      pageTitle,
      _i18n(en: 'Function Flow', zh: '函数流程'),
    ]);

    final nodes = (content['nodes'] as List? ?? []).whereType<Map>();
    final steps = (content['steps'] as List? ?? []).whereType<Map>();

    final nodeLines = nodes
        .where((n) {
          final label = (n['label'] as String? ?? '').trim();
          return label.isNotEmpty;
        })
        .map((n) {
          final label = (n['label'] as String? ?? '').trim();
          final desc = (n['description'] as String? ?? '').trim();
          return desc.isNotEmpty ? '• $label: $desc' : '• $label';
        })
        .join('\n');

    final results = <_QuestionData>[
      _QuestionData(
        type: QuestionType.info,
        title: title,
        content: nodeLines,
      ),
    ];

    var stepNum = 1;
    for (final step in steps) {
      final note = (step['note'] as String? ?? '').trim();
      if (note.isEmpty) continue;
      results.add(_QuestionData(
        type: QuestionType.info,
        title: _i18n(en: 'Step $stepNum', zh: '步骤 $stepNum'),
        content: note,
      ));
      stepNum++;
    }

    return results;
  }

  _QuestionData? _parseBlock({
    required String type,
    required Map<String, dynamic> content,
    required Map<String, dynamic> config,
    required String pageTitle,
  }) {
    final normalizedType = type.trim().toLowerCase().replaceAll('_', '-');

    switch (normalizedType) {
      case 'info-card':
      case 'text':
        final body = _firstNonEmptyString([
          content['value'],
          content['text'],
          content['body'],
          content['description'],
          config['text'],
          config['body'],
        ]);
        final title = _firstNonEmptyString([content['title']]);
        if (body.isEmpty) return null;
        return _QuestionData(
          type: QuestionType.info,
          title: title,
          content: body,
        );

      case 'multiple-choice':
        final promptTitle = _firstNonEmptyString([
          content['question'],
          content['title'],
          pageTitle,
          _i18n(en: 'Question', zh: '问题'),
        ]);
        final promptBody = _firstNonEmptyString([
          content['body'],
          content['description'],
          config['body'],
        ]);

        final rawOptions = content['options'] ?? config['options'];
        final options = <String>[];
        final optionIds = <String?>[];
        int? inferredCorrectIndex;

        if (rawOptions is List) {
          for (final option in rawOptions) {
            if (option is String && option.trim().isNotEmpty) {
              options.add(option.trim());
              optionIds.add(null);
              continue;
            }
            if (option is Map) {
              final map = Map<String, dynamic>.from(option);
              final text = _firstNonEmptyString([
                map['text'],
                map['label'],
                map['value'],
              ]);
              if (text.isEmpty) continue;
              options.add(text);
              optionIds.add((map['id'] as String?)?.trim());
              if (map['isCorrect'] == true && inferredCorrectIndex == null) {
                inferredCorrectIndex = options.length - 1;
              }
            }
          }
        }

        if (options.isEmpty) return null;

        final correctIndexRaw =
            config['correct_index'] ??
            content['correct_index'] ??
            config['correctIndex'] ??
            content['correctIndex'];
        int? correctIndex = _toInt(correctIndexRaw);

        if (correctIndex == null ||
            correctIndex < 0 ||
            correctIndex >= options.length) {
          correctIndex = inferredCorrectIndex;
        }

        if (correctIndex == null) {
          final candidateAnswers = <String>[
            _firstNonEmptyString([
              content['correct_answer'],
              content['correctAnswer'],
              config['correct_answer'],
              config['correctAnswer'],
            ]),
            ..._toStringList(content['correct_answers'] ?? content['correctAnswers']),
            ..._toStringList(config['correct_answers'] ?? config['correctAnswers']),
          ].where((e) => e.isNotEmpty).toList();

          for (final candidate in candidateAnswers) {
            final lower = candidate.toLowerCase();
            final byId = optionIds.indexWhere(
              (id) => id != null && id.toLowerCase() == lower,
            );
            if (byId >= 0) {
              correctIndex = byId;
              break;
            }
            final byText = options.indexWhere(
              (text) => text.toLowerCase() == lower,
            );
            if (byText >= 0) {
              correctIndex = byText;
              break;
            }
          }
        }
        final successMsg = _firstNonEmptyString([
          config['success_msg'],
          config['successMsg'],
          content['success_msg'],
          content['explanation'],
          _i18n(en: 'Correct!', zh: '回答正确！'),
        ]);
        final failMsg = _firstNonEmptyString([
          config['fail_msg'],
          config['failMsg'],
          content['fail_msg'],
          _i18n(en: "That's not right. Try again!", zh: '不太对，再试一次！'),
        ]);

        // Multi-select path
        final isMultiSelect =
            content['multi_select'] == true ||
            content['multiSelect'] == true ||
            config['multi_select'] == true ||
            config['multiSelect'] == true;

        if (isMultiSelect) {
          // Collect all correct answer IDs/texts
          final allCorrectRaw = [
            ..._toStringList(content['correct_answers'] ?? content['correctAnswers']),
            ..._toStringList(config['correct_answers'] ?? config['correctAnswers']),
          ].where((e) => e.isNotEmpty).toSet();

          final correctIndices = <int>{};
          for (final candidate in allCorrectRaw) {
            final lower = candidate.toLowerCase();
            final byId = optionIds.indexWhere(
              (id) => id != null && id.toLowerCase() == lower,
            );
            if (byId >= 0) {
              correctIndices.add(byId);
              continue;
            }
            final byText = options.indexWhere(
              (text) => text.toLowerCase() == lower,
            );
            if (byText >= 0) correctIndices.add(byText);
          }

          if (correctIndices.isEmpty) return null;

          return _QuestionData(
            type: QuestionType.multiChoice,
            title: promptTitle,
            content: promptBody,
            options: options,
            correctIndices: correctIndices,
            successMsg: successMsg,
            failMsg: failMsg,
          );
        }

        // Single-select path
        correctIndex ??= 0;

        return _QuestionData(
          type: QuestionType.choice,
          title: promptTitle,
          content: promptBody,
          options: options,
          correctIndex: correctIndex,
          successMsg: successMsg,
          failMsg: failMsg,
        );

      case 'fill-blank':
        final question = _firstNonEmptyString([
          content['question'],
          '${_firstNonEmptyString([content['before']])} ____ ${_firstNonEmptyString([content['after']])}'
              .trim(),
        ]);
        final answer = _firstNonEmptyString([
          content['correct_answer'],
          content['correctAnswer'],
          content['answer'],
          config['correct_answer'],
          config['correctAnswer'],
          config['answer'],
        ]);
        if (question.isEmpty || answer.isEmpty) return null;
        final hint = _firstNonEmptyString([content['hint'], config['hint']]);
        return _QuestionData(
          type: QuestionType.input,
          title: _firstNonEmptyString([
            pageTitle,
            _i18n(en: 'Fill in the Blank', zh: '填空题'),
          ]),
          content: hint.isNotEmpty
              ? '$question\n\n${_i18n(en: 'Hint', zh: '提示')}: $hint'
              : question,
          correctAnswer: answer,
          successMsg: _firstNonEmptyString([
            content['success_msg'],
            config['success_msg'],
            _i18n(en: 'Correct!', zh: '回答正确！'),
          ]),
          failMsg: _firstNonEmptyString([
            content['fail_msg'],
            config['fail_msg'],
            _i18n(en: 'Not quite. Try again!', zh: '还不完全正确，再试一次！'),
          ]),
        );

      case 'true-false':
        final statement = _firstNonEmptyString([
          content['question'],
          content['statement'],
        ]);
        if (statement.isEmpty) return null;
        final isTrue = _toBool(
          content['correct_answer'] ?? content['correctAnswer'] ?? content['isTrue'],
          true,
        );
        final explanation = _firstNonEmptyString([
          content['explanation'],
          config['explanation'],
        ]);
        return _QuestionData(
          type: QuestionType.choice,
          title: _i18n(en: 'True or False?', zh: '判断正误'),
          content: statement,
          options: [
            _i18n(en: 'True', zh: '正确'),
            _i18n(en: 'False', zh: '错误'),
          ],
          correctIndex: isTrue ? 0 : 1,
          successMsg: explanation.isNotEmpty
              ? explanation
              : _i18n(en: 'Correct!', zh: '回答正确！'),
          failMsg: explanation.isNotEmpty
              ? explanation
              : _i18n(en: "That's not right. Try again!", zh: '不太对，再试一次！'),
        );

      case 'code-block':
        final code = _firstNonEmptyString([content['code']]);
        if (code.isEmpty) return null;
        final language = _firstNonEmptyString([content['language']]);
        return _QuestionData(
          type: QuestionType.info,
          title: pageTitle.isNotEmpty
              ? pageTitle
              : (language.isNotEmpty
                    ? '${language.toUpperCase()} ${_i18n(en: 'Code', zh: '代码')}'
                    : _i18n(en: 'Code', zh: '代码')),
          content: '```${language.isNotEmpty ? language : ''}\n$code\n```',
        );

      case 'code-playground':
        final expectedOutput = _firstNonEmptyString([
          content['expected_output'],
          content['expectedOutput'],
        ]);
        final starterCode = _firstNonEmptyString([
          content['initial_code'],
          content['initialCode'],
          content['starterCode'],
        ]);
        if (expectedOutput.isNotEmpty) {
          return _QuestionData(
            type: QuestionType.input,
            title: _firstNonEmptyString([
              pageTitle,
              _i18n(en: 'Code Challenge', zh: '代码挑战'),
            ]),
            content: starterCode.isNotEmpty
                ? '${_i18n(en: 'Starting code', zh: '初始代码')}:\n$starterCode\n\n${_i18n(en: 'Expected output', zh: '期望输出')}: $expectedOutput'
                : '${_i18n(en: 'Expected output', zh: '期望输出')}: $expectedOutput',
            correctAnswer: expectedOutput,
            successMsg: _i18n(en: 'Correct output!', zh: '输出正确！'),
            failMsg: _i18n(
              en: "Output doesn't match. Try again!",
              zh: '输出不匹配，再试一次！',
            ),
          );
        }
        if (starterCode.isNotEmpty) {
          return _QuestionData(
            type: QuestionType.info,
            title: _firstNonEmptyString([
              pageTitle,
              _i18n(en: 'Code Example', zh: '代码示例'),
            ]),
            content: starterCode,
          );
        }
        return null;

      case 'image':
        final caption = _firstNonEmptyString([content['caption']]);
        final alt = _firstNonEmptyString([content['alt']]);
        final url = _firstNonEmptyString([content['url']]);
        if (url.isEmpty && caption.isEmpty && alt.isEmpty) return null;
        return _QuestionData(
          type: QuestionType.info,
          title: _firstNonEmptyString([
            pageTitle,
            _i18n(en: 'Visual', zh: '可视内容'),
          ]),
          content: _firstNonEmptyString([caption, alt]),
          imageUrl: url.isNotEmpty ? url : null,
        );

      case 'matching':
        final question = _firstNonEmptyString([
          content['question'],
          pageTitle,
          _i18n(en: 'Matching', zh: '配对题'),
        ]);

        // Graph mode: convert nodes + edges into left→right matching pairs.
        final isGraphMode = (content['mode'] as String?)?.trim() == 'graph';
        if (isGraphMode) {
          final rawNodes = content['nodes'];
          final rawEdges = content['edges'];
          if (rawNodes is! List || rawEdges is! List) return null;

          // Build nodeId → label map
          final nodeLabels = <String, String>{};
          for (final n in rawNodes) {
            if (n is Map) {
              final id = (n['id'] as String? ?? '').trim();
              final label = (n['label'] as String? ?? '').trim();
              if (id.isNotEmpty && label.isNotEmpty) nodeLabels[id] = label;
            }
          }

          // Convert edges to from-label → to-label pairs (deduplicate by from-label)
          final graphPairs = <String, String>{};
          for (final e in rawEdges) {
            if (e is Map) {
              final fromLabel = nodeLabels[(e['from'] as String? ?? '').trim()] ?? '';
              final toLabel = nodeLabels[(e['to'] as String? ?? '').trim()] ?? '';
              if (fromLabel.isNotEmpty && toLabel.isNotEmpty && !graphPairs.containsKey(fromLabel)) {
                graphPairs[fromLabel] = toLabel;
              }
            }
          }
          if (graphPairs.isEmpty) return null;

          final leftItems = graphPairs.keys.toList();
          final rightItems = graphPairs.values.toList();
          return _QuestionData(
            type: QuestionType.matching,
            title: question,
            content: '',
            matchingLeftItems: leftItems,
            matchingRightItems: List.from(rightItems)..shuffle(),
            matchingCorrectPairs: Map.from(graphPairs),
            successMsg: _i18n(en: 'All connections correct!', zh: '所有连接都正确！'),
            failMsg: _i18n(
              en: 'Some connections are wrong. Try again!',
              zh: '有些连接不正确，再试一次！',
            ),
            hints: leftItems
                .take(3)
                .map((l) => '"$l" → "${graphPairs[l]}"')
                .toList(),
          );
        }

        // List mode (default)
        final leftItems = _extractItemTexts(content['left_items'] ?? content['leftItems']);
        final rightItems = _extractItemTexts(content['right_items'] ?? content['rightItems']);
        if (leftItems.isEmpty || rightItems.isEmpty) return null;
        // Build correct pairs map: left text → right text
        final Map<String, String> correctPairs = {};
        final rawPairs = content['correct_pairs'] ?? content['correctPairs'] ?? content['pairs'];
        if (rawPairs is List) {
          for (final pair in rawPairs) {
            if (pair is Map) {
              final left = _firstNonEmptyString([pair['left'], pair['left_id'], pair['leftId']]);
              final right =
                  _firstNonEmptyString([pair['right'], pair['right_id'], pair['rightId']]);
              if (left.isNotEmpty && right.isNotEmpty) {
                correctPairs[left] = right;
              }
            }
          }
        }
        // If no explicit pairs, assume positional matching
        if (correctPairs.isEmpty) {
          final len = leftItems.length < rightItems.length
              ? leftItems.length
              : rightItems.length;
          for (int i = 0; i < len; i++) {
            correctPairs[leftItems[i]] = rightItems[i];
          }
        }
        return _QuestionData(
          type: QuestionType.matching,
          title: question,
          content: '',
          matchingLeftItems: leftItems,
          matchingRightItems: List.from(rightItems)..shuffle(),
          matchingCorrectPairs: correctPairs,
          successMsg: _i18n(en: 'All pairs matched!', zh: '所有配对都正确！'),
          failMsg: _i18n(
            en: 'Some pairs are incorrect. Try again!',
            zh: '有些配对不正确，再试一次！',
          ),
          hints: leftItems
              .where((l) => correctPairs.containsKey(l))
              .take(3)
              .map((l) => '"$l" → "${correctPairs[l]}"')
              .toList(),
        );

      case 'interactive-visual':
        return _QuestionData(
          type: QuestionType.interactiveVisual,
          title: _firstNonEmptyString([
            content['title'] as String?,
            pageTitle,
            _i18n(en: 'Interactive Visual', zh: '交互可视化'),
          ]),
          content: content['description'] as String? ?? '',
          visualSpec: content,
        );

      case 'animation':
      case 'video':
        return _QuestionData(
          type: QuestionType.info,
          title: _firstNonEmptyString([
            pageTitle,
            _i18n(en: 'Interactive Content', zh: '互动内容'),
          ]),
          content: _i18n(
            en: 'This block type is not interactive in Viewer yet.',
            zh: '该内容类型在 Viewer 中暂不支持交互。',
          ),
        );
    }
    return null;
  }

  Map<String, dynamic> _toMap(dynamic value) {
    if (value is Map<String, dynamic>) return value;
    if (value is Map) return Map<String, dynamic>.from(value);
    return <String, dynamic>{};
  }

  String _firstNonEmptyString(List<dynamic> values) {
    for (final value in values) {
      if (value is String) {
        final trimmed = value.trim();
        if (trimmed.isNotEmpty) return trimmed;
      }
    }
    return '';
  }

  List<String> _toStringList(dynamic value) {
    if (value is! List) return const [];
    return value
        .whereType<String>()
        .map((v) => v.trim())
        .where((v) => v.isNotEmpty)
        .toList();
  }

  int? _toInt(dynamic value) {
    if (value is int) return value;
    if (value is num) return value.toInt();
    if (value is String) return int.tryParse(value);
    return null;
  }

  bool _toBool(dynamic value, bool fallback) {
    if (value is bool) return value;
    if (value is String) {
      final lowered = value.toLowerCase();
      if (lowered == 'true') return true;
      if (lowered == 'false') return false;
    }
    return fallback;
  }

  List<String> _extractItemTexts(dynamic value) {
    if (value is! List) return const [];
    final out = <String>[];
    for (final item in value) {
      if (item is String && item.trim().isNotEmpty) {
        out.add(item.trim());
        continue;
      }
      if (item is Map) {
        final text = _firstNonEmptyString([
          item['text'],
          item['label'],
          item['value'],
        ]);
        if (text.isNotEmpty) out.add(text);
      }
    }
    return out;
  }

