import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:builder/models/models.dart';
import 'package:builder/services/id_generator.dart';
import 'package:builder/services/course_export.dart';

void main() {
  group('Block Model', () {
    test('Block.create generates valid block with ID', () {
      final block = Block.create(BlockType.text, order: 0);

      expect(block.id, isNotEmpty);
      expect(block.type, BlockType.text);
      expect(block.position.order, 0);
      expect(block.content, isA<TextContent>());
    });

    test('Block JSON serialization roundtrip', () {
      final block = Block.create(BlockType.text, order: 1);
      final json = block.toJson();
      final restored = Block.fromJson(json);

      expect(restored.id, block.id);
      expect(restored.type, block.type);
      expect(restored.position.order, block.position.order);
    });

    test('Block copyWith preserves values', () {
      final block = Block.create(BlockType.text, order: 0);
      final copied = block.copyWith(position: BlockPosition(order: 5));

      expect(copied.id, block.id);
      expect(copied.type, block.type);
      expect(copied.position.order, 5);
    });

    test('Block.create defaults visibilityRule to always', () {
      final block = Block.create(BlockType.text, order: 0);
      expect(block.visibilityRule, 'always');
    });

    test('Block.create defaults non-first visibilityRule to gated', () {
      final block = Block.create(BlockType.text, order: 1);
      expect(block.visibilityRule, 'afterPreviousCorrect');
    });

    test('Block visibilityRule serializes to JSON', () {
      final block = Block.create(
        BlockType.text,
        order: 0,
      ).copyWith(visibilityRule: 'afterPreviousCorrect');
      final json = block.toJson();

      expect(json['visibility_rule'], 'afterPreviousCorrect');
    });

    test('Block visibilityRule deserializes from JSON', () {
      final block = Block.create(BlockType.text, order: 0);
      final json = block.toJson();
      json['visibility_rule'] = 'afterPreviousCorrect';
      final restored = Block.fromJson(json);

      expect(restored.visibilityRule, 'afterPreviousCorrect');
    });

    test('Block visibilityRule defaults to always when missing from JSON', () {
      final block = Block.create(BlockType.text, order: 0);
      final json = block.toJson();
      json.remove('visibility_rule');
      final restored = Block.fromJson(json);

      expect(restored.visibilityRule, 'always');
    });

    test(
      'Block visibilityRule defaults to afterPreviousCorrect when non-first JSON is missing rule',
      () {
        final block = Block.create(BlockType.text, order: 2);
        final json = block.toJson();
        json.remove('visibility_rule');
        final restored = Block.fromJson(json);

        expect(restored.visibilityRule, 'afterPreviousCorrect');
      },
    );

    test('Block copyWith updates visibilityRule', () {
      final block = Block.create(BlockType.text, order: 0);
      final updated = block.copyWith(visibilityRule: 'afterPreviousCorrect');

      expect(updated.visibilityRule, 'afterPreviousCorrect');
      expect(updated.id, block.id);
    });

    test('Block JSON roundtrip preserves visibilityRule', () {
      final block = Block.create(
        BlockType.multipleChoice,
        order: 0,
      ).copyWith(visibilityRule: 'afterPreviousCorrect');
      final json = block.toJson();
      final restored = Block.fromJson(json);

      expect(restored.visibilityRule, 'afterPreviousCorrect');
      expect(restored.type, BlockType.multipleChoice);
    });
  });

  group('TextContent', () {
    test('TextContent serialization', () {
      const content = TextContent(format: 'markdown', value: '# Hello');
      final json = content.toJson();

      expect(json['format'], 'markdown');
      expect(json['value'], '# Hello');
    });

    test('TextContent deserialization', () {
      final json = {'format': 'plain', 'value': 'Test text'};
      final content = TextContent.fromJson(json);

      expect(content.format, 'plain');
      expect(content.value, 'Test text');
    });

    test('TextContent defaults to richtext format', () {
      const content = TextContent(value: 'some text');
      expect(content.format, 'richtext');
    });

    test('TextContent copyWith switches format', () {
      const content = TextContent(format: 'plain', value: 'hello');
      final switched = content.copyWith(format: 'markdown');

      expect(switched.format, 'markdown');
      expect(switched.value, 'hello');
    });

    test('TextContent roundtrip preserves format', () {
      const content = TextContent(format: 'plain', value: 'plain text');
      final json = content.toJson();
      final restored = TextContent.fromJson(json);

      expect(restored.format, 'plain');
      expect(restored.value, 'plain text');
    });

    test('TextContent fromJson defaults format to richtext when missing', () {
      final json = {'value': 'no format field'};
      final content = TextContent.fromJson(json);

      expect(content.format, 'richtext');
      expect(content.value, 'no format field');
    });

    test('TextContent handles markdown syntax in value', () {
      const mdValue =
          '# Heading\n\n**bold** and *italic*\n\n- item 1\n- item 2\n\n`code`';
      const content = TextContent(format: 'markdown', value: mdValue);
      final json = content.toJson();
      final restored = TextContent.fromJson(json);

      expect(restored.format, 'markdown');
      expect(restored.value, mdValue);
    });

    test('TextContent handles malformed markdown without error', () {
      const malformed =
          '# Unclosed **bold\n\n```\nno closing fence\n\n[broken link(';
      const content = TextContent(format: 'markdown', value: malformed);
      final json = content.toJson();
      final restored = TextContent.fromJson(json);

      expect(restored.value, malformed);
      expect(restored.format, 'markdown');
    });
  });

  group('CodePlaygroundContent', () {
    test('CodePlaygroundContent serialization', () {
      const content = CodePlaygroundContent(
        language: 'python',
        initialCode: 'print("Hello")',
        expectedOutput: 'Hello',
        hints: ['Use print function'],
        runnable: true,
      );
      final json = content.toJson();

      expect(json['language'], 'python');
      expect(json['initialCode'], 'print("Hello")');
      expect(json['expectedOutput'], 'Hello');
      expect(json['hints'], ['Use print function']);
      expect(json['runnable'], true);
    });

    test('CodePlaygroundContent deserialization', () {
      final json = {
        'language': 'javascript',
        'initialCode': 'console.log("Hi")',
        'expectedOutput': 'Hi',
        'hints': [],
        'runnable': false,
      };
      final content = CodePlaygroundContent.fromJson(json);

      expect(content.language, 'javascript');
      expect(content.initialCode, 'console.log("Hi")');
      expect(content.expectedOutput, 'Hi');
      expect(content.runnable, false);
    });
  });

  group('AnimationContent', () {
    test('AnimationContent serialization', () {
      const content = AnimationContent(
        preset: AnimationContent.presetPulseBars,
        durationMs: 1800,
        loop: false,
        speed: 1.5,
      );
      final json = content.toJson();

      expect(json['preset'], AnimationContent.presetPulseBars);
      expect(json['durationMs'], 1800);
      expect(json['loop'], false);
      expect(json['speed'], 1.5);
    });

    test('AnimationContent deserialization with normalization', () {
      final json = {
        'preset': 'unknown-preset',
        'durationMs': 120,
        'loop': true,
        'speed': 10,
      };
      final content = AnimationContent.fromJson(json);

      expect(content.preset, AnimationContent.presetBouncingDot);
      expect(content.durationMs, 300);
      expect(content.loop, isTrue);
      expect(content.speed, 3.0);
    });

    test('Block.create animation uses AnimationContent defaults', () {
      final block = Block.create(BlockType.animation, order: 0);

      expect(block.content, isA<AnimationContent>());
      final content = block.content as AnimationContent;
      expect(content.preset, AnimationContent.presetBouncingDot);
      expect(content.durationMs, 2000);
      expect(content.loop, isTrue);
      expect(content.speed, 1.0);
    });

    test(
      'AnimationContent custom preset serializes customHtml and aiPrompt',
      () {
        const content = AnimationContent(
          preset: AnimationContent.presetCustom,
          customHtml: '<html><body>test</body></html>',
          aiPrompt: 'Show bubble sort',
        );
        final json = content.toJson();

        expect(json['preset'], AnimationContent.presetCustom);
        expect(json['customHtml'], '<html><body>test</body></html>');
        expect(json['aiPrompt'], 'Show bubble sort');

        final roundtrip = AnimationContent.fromJson(json);
        expect(roundtrip.preset, AnimationContent.presetCustom);
        expect(roundtrip.customHtml, '<html><body>test</body></html>');
        expect(roundtrip.aiPrompt, 'Show bubble sort');
      },
    );

    test('AnimationContent copyWith clearCustomHtml removes customHtml', () {
      const content = AnimationContent(
        preset: AnimationContent.presetCustom,
        customHtml: '<html/>',
        aiPrompt: 'test',
      );
      final cleared = content.copyWith(
        preset: AnimationContent.presetBouncingDot,
        clearCustomHtml: true,
      );
      expect(cleared.customHtml, isNull);
      expect(cleared.preset, AnimationContent.presetBouncingDot);
    });
  });

  group('FunctionFlowContent', () {
    test('FunctionFlowContent serialization roundtrip', () {
      final content = FunctionFlowContent(
        title: 'Call graph',
        nodes: const [
          FunctionFlowNode(
            id: 'start',
            label: 'Start',
            x: 10,
            y: 50,
            kind: FunctionFlowNode.kindStart,
          ),
          FunctionFlowNode(
            id: 'solve',
            label: 'solve()',
            x: 50,
            y: 50,
            description: 'Core function',
          ),
          FunctionFlowNode(
            id: 'end',
            label: 'End',
            x: 90,
            y: 50,
            kind: FunctionFlowNode.kindEnd,
          ),
        ],
        edges: const [
          FunctionFlowEdge(from: 'start', to: 'solve', label: 'call'),
          FunctionFlowEdge(from: 'solve', to: 'end', label: 'return'),
        ],
        entryNodeId: 'start',
        steps: const [
          FunctionFlowStep(edgeIndex: 0, note: 'call solve'),
          FunctionFlowStep(edgeIndex: 1, note: 'return'),
        ],
        style: const FunctionFlowStyle(
          theme: 'emerald',
          showArrows: true,
          stepDurationMs: 1400,
          lineWidth: 2.5,
        ),
      );

      final json = content.toJson();
      final restored = FunctionFlowContent.fromJson(json);

      expect(restored.title, 'Call graph');
      expect(restored.nodes.length, 3);
      expect(restored.edges.length, 2);
      expect(restored.steps.length, 2);
      expect(restored.entryNodeId, 'start');
      expect(restored.style.theme, 'emerald');
      expect(restored.style.stepDurationMs, 1400);
    });

    test('Block.create function-flow uses defaults', () {
      final block = Block.create(BlockType.functionFlow, order: 0);
      expect(block.type, BlockType.functionFlow);
      expect(block.content, isA<FunctionFlowContent>());

      final content = block.content as FunctionFlowContent;
      expect(content.nodes.length, greaterThanOrEqualTo(2));
      expect(content.edges.length, greaterThanOrEqualTo(1));
      expect(content.style.stepDurationMs, 1200);
    });
  });

  group('CodeExecutionContent', () {
    test('serialization roundtrip preserves execution fields', () {
      const content = CodeExecutionContent(
        title: 'Trace Loop',
        language: 'python',
        sourceCode: 'x = 1\\ny = x + 2\\nprint(y)',
        traceSteps: [
          CodeExecutionTraceStep(line: 1, variables: {'x': 1}),
          CodeExecutionTraceStep(
            line: 2,
            variables: {'x': 1, 'y': 3},
            note: 'y computed',
          ),
          CodeExecutionTraceStep(
            line: 3,
            variables: {'x': 1, 'y': 3},
            stdoutDelta: '3',
          ),
        ],
        initialVariables: {'seed': 0},
        checkpoints: [
          CodeExecutionCheckpoint(
            stepIndex: 1,
            question: 'What is y?',
            options: ['2', '3'],
            correctIndex: 1,
            explanation: 'x + 2',
          ),
        ],
        controls: CodeExecutionControls(
          autoplay: false,
          stepDurationMs: 900,
          allowScrub: true,
        ),
        style: CodeExecutionStyle(
          theme: 'emerald',
          showLineNumbers: true,
          showVariablesPanel: true,
          showStdoutPanel: true,
        ),
      );

      final restored = CodeExecutionContent.fromJson(content.toJson());
      expect(restored.title, 'Trace Loop');
      expect(restored.language, 'python');
      expect(restored.sourceCode, contains('print(y)'));
      expect(restored.traceSteps.length, 3);
      expect(restored.traceSteps[1].line, 2);
      expect(restored.traceSteps[2].stdoutDelta, '3');
      expect(restored.initialVariables['seed'], 0);
      expect(restored.checkpoints.length, 1);
      expect(restored.checkpoints.first.correctIndex, 1);
      expect(restored.controls.stepDurationMs, 900);
      expect(restored.style.theme, 'emerald');
    });

    test('fromJson supports legacy code field fallback', () {
      final content = CodeExecutionContent.fromJson({
        'title': 'Legacy',
        'language': 'python',
        'code': 'print(\"legacy\")',
        'traceSteps': [
          {'line': 1, 'variables': {}},
        ],
      });

      expect(content.sourceCode, 'print(\"legacy\")');
      expect(content.traceSteps.length, 1);
    });

    test('Block.create code-execution has default trace', () {
      final block = Block.create(BlockType.codeExecution, order: 0);
      expect(block.type, BlockType.codeExecution);
      final content = block.content as CodeExecutionContent;
      expect(content.traceSteps.isNotEmpty, isTrue);
      expect(content.controls.stepDurationMs, 1200);
      expect(content.style.showLineNumbers, isTrue);
    });
  });

  group('MultipleChoiceContent', () {
    test('MultipleChoiceContent serialization', () {
      final content = MultipleChoiceContent(
        question: 'What is 2+2?',
        options: [
          const ChoiceOption(id: 'a', text: '3'),
          const ChoiceOption(id: 'b', text: '4'),
          const ChoiceOption(id: 'c', text: '5'),
        ],
        correctAnswer: 'b',
        correctAnswers: ['b'],
        explanation: 'Basic arithmetic',
        multiSelect: false,
      );
      final json = content.toJson();

      expect(json['question'], 'What is 2+2?');
      expect(json['options'].length, 3);
      expect(json['correctAnswer'], 'b');
      expect(json['correctAnswers'], ['b']);
      expect(json['explanation'], 'Basic arithmetic');
    });

    test('MultipleChoiceContent fromJson supports multi-answer list', () {
      final json = {
        'question': 'Select prime numbers',
        'options': [
          {'id': 'a', 'text': '2'},
          {'id': 'b', 'text': '3'},
          {'id': 'c', 'text': '4'},
        ],
        'correctAnswers': ['b', 'a'],
        'multiSelect': true,
      };

      final content = MultipleChoiceContent.fromJson(json);
      expect(content.multiSelect, isTrue);
      expect(content.normalizedCorrectAnswers, ['b', 'a']);
      expect(content.primaryCorrectAnswer, 'b');
    });

    test(
      'MultipleChoiceContent fromJson falls back to legacy correctAnswer',
      () {
        final json = {
          'question': 'Fallback',
          'options': [
            {'id': 'a', 'text': 'A'},
            {'id': 'b', 'text': 'B'},
          ],
          'correctAnswer': 'a',
          'multiSelect': false,
        };

        final content = MultipleChoiceContent.fromJson(json);
        expect(content.normalizedCorrectAnswers, ['a']);
        expect(content.primaryCorrectAnswer, 'a');
      },
    );
  });

  group('CourseLesson Model', () {
    test('CourseLesson.create generates valid lesson', () {
      final lesson = CourseLesson.create(title: 'Test Lesson');

      expect(lesson.lessonId, isNotEmpty);
      expect(lesson.title, 'Test Lesson');
      expect(lesson.pages.first.blocks, isEmpty);
    });

    test('CourseLesson addBlock', () {
      final lesson = CourseLesson.create(title: 'Test');
      final block = Block.create(BlockType.text, order: 0);
      final updated = lesson.addBlock(block);

      expect(updated.pages.first.blocks.length, 1);
      expect(updated.pages.first.blocks.first.id, block.id);
    });

    test('CourseLesson removeBlock', () {
      final lesson = CourseLesson.create(title: 'Test');
      final block = Block.create(BlockType.text, order: 0);
      final withBlock = lesson.addBlock(block);
      final removed = withBlock.removeBlock(block.id);

      expect(removed.pages.first.blocks.length, 0);
    });

    test('CourseLesson reorderBlocks', () {
      final lesson = CourseLesson.create(title: 'Test');
      final block1 = Block.create(BlockType.text, order: 0);
      final block2 = Block.create(BlockType.image, order: 1);
      final withBlocks = lesson.addBlock(block1).addBlock(block2);
      final reordered = withBlocks.reorderBlocks(0, 1);

      expect(reordered.pages.first.blocks[0].id, block2.id);
      expect(reordered.pages.first.blocks[1].id, block1.id);
      expect(reordered.pages.first.blocks[0].position.order, 0);
      expect(reordered.pages.first.blocks[1].position.order, 1);
    });

    test('CourseLesson JSON roundtrip', () {
      final lesson = CourseLesson.create(title: 'Test Lesson');
      final block = Block.create(BlockType.text, order: 0);
      final withBlock = lesson.addBlock(block);

      final json = withBlock.toJson();
      final restored = CourseLesson.fromJson(json);

      expect(restored.lessonId, withBlock.lessonId);
      expect(restored.title, withBlock.title);
      expect(restored.pages.first.blocks.length, 1);
    });

    test('CourseLesson fromJson accepts legacy pageId key', () {
      final json = {
        'pageId': 'legacy-page-id',
        'title': 'Legacy Lesson',
        'blocks': <dynamic>[],
      };
      final lesson = CourseLesson.fromJson(json);

      expect(lesson.lessonId, 'legacy-page-id');
      expect(lesson.title, 'Legacy Lesson');
    });
  });

  group('Course Model', () {
    test('Course.create generates valid course', () {
      final course = Course.create(title: 'My Course');

      expect(course.courseId, isNotEmpty);
      expect(course.metadata.title, 'My Course');
      expect(course.lessons.length, 1);
    });

    test('Course addLesson', () {
      final course = Course.create(title: 'Test');
      final newLesson = CourseLesson.create(title: 'Lesson 2');
      final updated = course.addLesson(newLesson);

      expect(updated.lessons.length, 2);
    });

    test('Course removeLesson', () {
      final course = Course.create(title: 'Test');
      final newLesson = CourseLesson.create(title: 'Lesson 2');
      final withLesson = course.addLesson(newLesson);
      final removed = withLesson.removeLesson(newLesson.lessonId);

      expect(removed.lessons.length, 1);
    });

    test('Course getLesson', () {
      final course = Course.create(title: 'Test');

      expect(course.getLesson(0), isNotNull);
      expect(course.getLesson(1), isNull);
      expect(course.getLesson(-1), isNull);
    });

    test('CourseLesson reports first non-empty page correctly', () {
      final lesson = CourseLesson.create(title: 'Paged Lesson').copyWith(
        pages: [
          LessonPage.create(order: 0),
          LessonPage.create(
            order: 1,
          ).copyWith(blocks: [Block.create(BlockType.text, order: 0)]),
        ],
      );

      expect(lesson.hasContent, isTrue);
      expect(lesson.firstNonEmptyPageIndex, 1);
    });

    test('Course firstNonEmptyPageLocation finds content across lessons', () {
      final emptyLesson = CourseLesson.create(title: 'Empty Lesson');
      final filledLesson = CourseLesson.create(title: 'Filled Lesson').copyWith(
        pages: [
          LessonPage.create(order: 0),
          LessonPage.create(
            order: 1,
          ).copyWith(blocks: [Block.create(BlockType.codeBlock, order: 0)]),
        ],
      );

      final course = Course.create(
        title: 'Test Course',
      ).copyWith(lessons: [emptyLesson, filledLesson]);

      expect(course.firstNonEmptyPageLocation(), (1, 1));
    });

    test(
      'Course firstNonEmptyPageLocation honors preferred lesson when it has content',
      () {
        final preferredLesson = CourseLesson.create(title: 'Preferred')
            .copyWith(
              pages: [
                LessonPage.create(order: 0),
                LessonPage.create(order: 1).copyWith(
                  blocks: [Block.create(BlockType.multipleChoice, order: 0)],
                ),
              ],
            );
        final laterLesson = CourseLesson.create(title: 'Later').copyWith(
          pages: [
            LessonPage.create(
              order: 0,
            ).copyWith(blocks: [Block.create(BlockType.text, order: 0)]),
          ],
        );

        final course = Course.create(
          title: 'Test Course',
        ).copyWith(lessons: [preferredLesson, laterLesson]);

        expect(course.firstNonEmptyPageLocation(preferredLessonIndex: 0), (
          0,
          1,
        ));
      },
    );

    test('Course JSON roundtrip', () {
      final course = Course.create(title: 'Full Course');
      final lesson = course.lessons.first;
      final block = Block.create(BlockType.codePlayground, order: 0);
      final updatedLesson = lesson.addBlock(block);
      final updatedCourse = course.updateLesson(updatedLesson);

      final json = updatedCourse.toJson();
      final jsonString = jsonEncode(json);
      final decoded = jsonDecode(jsonString) as Map<String, dynamic>;
      final restored = Course.fromJson(decoded);

      expect(restored.courseId, updatedCourse.courseId);
      expect(restored.metadata.title, 'Full Course');
      expect(restored.lessons.length, 1);
      expect(restored.lessons.first.pages.first.blocks.length, 1);
      expect(
        restored.lessons.first.pages.first.blocks.first.type,
        BlockType.codePlayground,
      );
    });

    test('Course JSON schema fields', () {
      final course = Course.create(title: 'Schema Test');
      final json = course.toJson();

      expect(json['\$schema'], isNotNull);
      expect(json['schemaVersion'], '1.0.0');
      expect(json['courseId'], isNotEmpty);
      expect(json['metadata'], isNotNull);
      expect(json['settings'], isNotNull);
      expect(json['lessons'], isA<List>());
    });

    test('Course fromJson accepts legacy pages key', () {
      final json = {
        'courseId': 'test-course',
        'metadata': {
          'title': 'Legacy Course',
          'description': '',
          'author': {'userId': 'u1', 'displayName': 'Test'},
          'tags': <String>[],
          'difficulty': 'beginner',
          'estimatedMinutes': 0,
          'createdAt': DateTime.now().toIso8601String(),
          'updatedAt': DateTime.now().toIso8601String(),
          'version': '1.0.0',
        },
        'settings': <String, dynamic>{},
        'pages': [
          {'pageId': 'page-1', 'title': 'Old Page', 'blocks': <dynamic>[]},
        ],
      };
      final course = Course.fromJson(json);

      expect(course.lessons.length, 1);
      expect(course.lessons.first.title, 'Old Page');
      expect(course.lessons.first.lessonId, 'page-1');
    });
  });

  group('IdGenerator', () {
    test('generates unique IDs', () {
      final ids = List.generate(100, (_) => IdGenerator.generate());
      final uniqueIds = ids.toSet();

      expect(uniqueIds.length, 100);
    });

    test('courseId has correct prefix', () {
      final id = IdGenerator.courseId();
      expect(id.startsWith('course-'), true);
    });

    test('lessonId has correct prefix', () {
      final id = IdGenerator.lessonId();
      expect(id.startsWith('lesson-'), true);
    });

    test('blockId has correct prefix', () {
      final id = IdGenerator.blockId();
      expect(id.startsWith('block-'), true);
    });
  });

  group('BlockType', () {
    test('BlockType values', () {
      expect(BlockType.text.value, 'text');
      expect(BlockType.image.value, 'image');
      expect(BlockType.codeBlock.value, 'code-block');
      expect(BlockType.codePlayground.value, 'code-playground');
      expect(BlockType.codeExecution.value, 'code-execution');
      expect(BlockType.multipleChoice.value, 'multiple-choice');
    });

    test('BlockType fromValue', () {
      expect(BlockType.fromValue('text'), BlockType.text);
      expect(BlockType.fromValue('code-playground'), BlockType.codePlayground);
    });

    test('BlockType labels', () {
      expect(BlockType.text.label, isNotEmpty);
      expect(BlockType.codePlayground.label, isNotEmpty);
    });
  });

  group('MatchingContent', () {
    test('default values', () {
      const content = MatchingContent();
      expect(content.question, '');
      expect(content.leftItems, isEmpty);
      expect(content.rightItems, isEmpty);
      expect(content.correctPairs, isEmpty);
      expect(content.explanation, isNull);
    });

    test('fromJson parses correctly', () {
      final json = {
        'question': 'Match capitals',
        'leftItems': [
          {'id': 'l1', 'text': 'France'},
          {'id': 'l2', 'text': 'Germany'},
        ],
        'rightItems': [
          {'id': 'r1', 'text': 'Paris'},
          {'id': 'r2', 'text': 'Berlin'},
        ],
        'correctPairs': [
          {'leftId': 'l1', 'rightId': 'r1'},
          {'leftId': 'l2', 'rightId': 'r2'},
        ],
        'explanation': 'Geography basics',
      };

      final content = MatchingContent.fromJson(json);
      expect(content.question, 'Match capitals');
      expect(content.leftItems.length, 2);
      expect(content.rightItems.length, 2);
      expect(content.correctPairs.length, 2);
      expect(content.correctPairs[0].leftId, 'l1');
      expect(content.correctPairs[0].rightId, 'r1');
      expect(content.explanation, 'Geography basics');
    });

    test('toJson roundtrip', () {
      const content = MatchingContent(
        question: 'Test Q',
        leftItems: [
          MatchingItem(id: 'a', text: 'A'),
          MatchingItem(id: 'b', text: 'B'),
        ],
        rightItems: [
          MatchingItem(id: 'x', text: 'X'),
          MatchingItem(id: 'y', text: 'Y'),
        ],
        correctPairs: [
          MatchingPair(leftId: 'a', rightId: 'x'),
          MatchingPair(leftId: 'b', rightId: 'y'),
        ],
        explanation: 'Explanation',
      );

      final json = content.toJson();
      final restored = MatchingContent.fromJson(json);

      expect(restored.question, content.question);
      expect(restored.leftItems.length, content.leftItems.length);
      expect(restored.rightItems.length, content.rightItems.length);
      expect(restored.correctPairs.length, content.correctPairs.length);
      expect(restored.explanation, content.explanation);
    });

    test('copyWith updates fields', () {
      const original = MatchingContent(
        question: 'Original',
        leftItems: [MatchingItem(id: 'l1', text: 'L1')],
        rightItems: [MatchingItem(id: 'r1', text: 'R1')],
        correctPairs: [MatchingPair(leftId: 'l1', rightId: 'r1')],
      );

      final updated = original.copyWith(question: 'Updated');
      expect(updated.question, 'Updated');
      expect(updated.leftItems.length, 1);
      expect(updated.correctPairs.length, 1);
    });

    test('fromJson handles empty lists gracefully', () {
      final json = {'question': 'Empty'};
      final content = MatchingContent.fromJson(json);

      expect(content.question, 'Empty');
      expect(content.leftItems, isEmpty);
      expect(content.rightItems, isEmpty);
      expect(content.correctPairs, isEmpty);
    });

    test('fromJson handles null explanation', () {
      final json = {
        'question': 'Q',
        'leftItems': <dynamic>[],
        'rightItems': <dynamic>[],
        'correctPairs': <dynamic>[],
      };
      final content = MatchingContent.fromJson(json);
      expect(content.explanation, isNull);
    });

    test('legacy matching infers graph fields while keeping list mode', () {
      final json = {
        'question': 'Match terms',
        'leftItems': [
          {'id': 'l1', 'text': 'CPU'},
          {'id': 'l2', 'text': 'RAM'},
        ],
        'rightItems': [
          {'id': 'r1', 'text': 'Processor'},
          {'id': 'r2', 'text': 'Memory'},
        ],
        'correctPairs': [
          {'leftId': 'l1', 'rightId': 'r1'},
          {'leftId': 'l2', 'rightId': 'r2'},
        ],
      };

      final content = MatchingContent.fromJson(json);
      expect(content.mode, MatchingContent.modeList);
      expect(content.nodes.length, 4);
      expect(content.edges.length, 2);
      expect(content.rules.directed, isTrue);
    });

    test('graph mode serializes nodes, edges, and rules', () {
      const content = MatchingContent(
        question: 'Connect system flow',
        mode: MatchingContent.modeGraph,
        nodes: [
          MatchingNode(
            id: 'n1',
            label: 'Input',
            x: 15,
            y: 40,
            group: MatchingNode.groupLeft,
          ),
          MatchingNode(
            id: 'n2',
            label: 'Parser',
            x: 55,
            y: 40,
            group: MatchingNode.groupNeutral,
          ),
          MatchingNode(
            id: 'n3',
            label: 'Output',
            x: 85,
            y: 40,
            group: MatchingNode.groupRight,
          ),
        ],
        edges: [
          MatchingEdge(from: 'n1', to: 'n2', label: 'feed', directed: true),
          MatchingEdge(from: 'n2', to: 'n3', directed: true),
        ],
        rules: MatchingRules(
          allowOneToMany: true,
          allowManyToMany: false,
          directed: true,
        ),
      );

      final restored = MatchingContent.fromJson(content.toJson());
      expect(restored.mode, MatchingContent.modeGraph);
      expect(restored.nodes.length, 3);
      expect(restored.edges.length, 2);
      expect(restored.edges.first.from, 'n1');
      expect(restored.rules.allowOneToMany, isTrue);
      expect(restored.rules.allowManyToMany, isFalse);
      expect(restored.rules.directed, isTrue);
    });
  });

  group('Export validation — Matching', () {
    Course buildCourseWithMatching(MatchingContent matchingContent) {
      final block = Block(
        id: 'b1',
        type: BlockType.matching,
        position: const BlockPosition(order: 0),
        style: const BlockStyle(),
        content: matchingContent,
      );
      final course = Course.create(title: 'Test Course');
      final lesson = course.lessons.first.addBlock(block);
      return course.updateLesson(lesson);
    }

    test('valid matching passes validation', () {
      final course = buildCourseWithMatching(
        const MatchingContent(
          question: 'Match these',
          leftItems: [
            MatchingItem(id: 'l1', text: 'A'),
            MatchingItem(id: 'l2', text: 'B'),
          ],
          rightItems: [
            MatchingItem(id: 'r1', text: 'X'),
            MatchingItem(id: 'r2', text: 'Y'),
          ],
          correctPairs: [
            MatchingPair(leftId: 'l1', rightId: 'r1'),
            MatchingPair(leftId: 'l2', rightId: 'r2'),
          ],
        ),
      );
      final result = CourseExport.validateForExport(course);
      expect(result.isValid, isTrue);
    });

    test('empty question fails', () {
      final course = buildCourseWithMatching(
        const MatchingContent(
          question: '',
          leftItems: [
            MatchingItem(id: 'l1', text: 'A'),
            MatchingItem(id: 'l2', text: 'B'),
          ],
          rightItems: [
            MatchingItem(id: 'r1', text: 'X'),
            MatchingItem(id: 'r2', text: 'Y'),
          ],
          correctPairs: [],
        ),
      );
      final result = CourseExport.validateForExport(course);
      expect(result.errors, contains(contains('question cannot be empty')));
    });

    test('fewer than 2 left items fails', () {
      final course = buildCourseWithMatching(
        const MatchingContent(
          question: 'Q',
          leftItems: [MatchingItem(id: 'l1', text: 'A')],
          rightItems: [
            MatchingItem(id: 'r1', text: 'X'),
            MatchingItem(id: 'r2', text: 'Y'),
          ],
          correctPairs: [],
        ),
      );
      final result = CourseExport.validateForExport(course);
      expect(result.errors, contains(contains('at least 2 left items')));
    });

    test('invalid pair reference fails', () {
      final course = buildCourseWithMatching(
        const MatchingContent(
          question: 'Q',
          leftItems: [
            MatchingItem(id: 'l1', text: 'A'),
            MatchingItem(id: 'l2', text: 'B'),
          ],
          rightItems: [
            MatchingItem(id: 'r1', text: 'X'),
            MatchingItem(id: 'r2', text: 'Y'),
          ],
          correctPairs: [
            MatchingPair(leftId: 'l1', rightId: 'r1'),
            MatchingPair(leftId: 'l999', rightId: 'r2'),
          ],
        ),
      );
      final result = CourseExport.validateForExport(course);
      expect(result.errors, contains(contains('unknown left id')));
    });
  });
}

