  Widget _buildMarkdownContent(String content, bool isDark) {
    final textColor = isDark ? AppColors.textOnDark : AppColors.textPrimary;
    final baseText = AppTypography.body1.copyWith(
      height: 1.6,
      color: textColor,
    );
    final codeBackground = isDark
        ? AppColors.cardDark
        : AppColors.surfaceVariant;

    return MarkdownBody(
      data: content,
      styleSheet: MarkdownStyleSheet.fromTheme(Theme.of(context)).copyWith(
        p: baseText,
        h1: AppTypography.headline1.copyWith(color: textColor),
        h2: AppTypography.headline2.copyWith(color: textColor),
        h3: AppTypography.headline3.copyWith(color: textColor),
        h4: AppTypography.title.copyWith(color: textColor),
        code: AppTypography.body2.copyWith(
          color: textColor,
          backgroundColor: codeBackground,
          fontFamily: 'monospace',
        ),
        blockquote: baseText.copyWith(fontStyle: FontStyle.italic),
        listBullet: baseText,
        codeblockPadding: const EdgeInsets.all(AppSpacing.md),
        codeblockDecoration: BoxDecoration(
          color: codeBackground,
          borderRadius: AppRadius.borderRadiusLg,
          border: Border.all(
            color: isDark ? AppColors.borderDark : AppColors.border,
          ),
        ),
      ),
    );
  }

  bool _isSameDisplayTitle(String left, String right) {
    String normalize(String input) =>
        input.trim().replaceAll(RegExp(r'\s+'), ' ').toLowerCase();

    final a = normalize(left);
    final b = normalize(right);
    return a.isNotEmpty && b.isNotEmpty && a == b;
  }

  Widget _buildInteractionWidget(
    _QuestionData question,
    bool isDark,
    AppLocalizations t,
  ) {
    switch (question.type) {
      case QuestionType.choice:
        return Column(
          children: question.options!.asMap().entries.map((entry) {
            final index = entry.key;
            final option = entry.value;
            final isSelected = _selectedOption == option;
            final label = String.fromCharCode(65 + index); // A, B, C, D
            return Padding(
              padding: const EdgeInsets.only(bottom: AppSpacing.md),
              child: GestureDetector(
                onTap: () {
                  _audioService.playClick();
                  setState(() => _selectedOption = option);
                },
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 150),
                  padding: const EdgeInsets.all(AppSpacing.md),
                  decoration: BoxDecoration(
                    color: isSelected
                        ? AppColors.primary.withValues(alpha: 0.08)
                        : isDark
                        ? AppColors.cardDark
                        : AppColors.surface,
                    borderRadius: AppRadius.borderRadiusXl,
                    border: Border.all(
                      color: isSelected
                          ? AppColors.primary
                          : isDark
                          ? AppColors.borderDark
                          : AppColors.border,
                      width: isSelected ? 2 : 1,
                    ),
                    boxShadow: isSelected ? AppShadows.sm : null,
                  ),
                  child: Row(
                    children: [
                      Container(
                        width: 32,
                        height: 32,
                        decoration: BoxDecoration(
                          color: isSelected
                              ? AppColors.primary
                              : isDark
                              ? AppColors.surfaceDark
                              : AppColors.surfaceVariant,
                          borderRadius: BorderRadius.circular(8),
                          border: isSelected
                              ? null
                              : Border.all(
                                  color: isDark
                                      ? AppColors.borderDark
                                      : AppColors.border,
                                ),
                        ),
                        child: Center(
                          child: Text(
                            label,
                            style: TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w700,
                              color: isSelected
                                  ? Colors.white
                                  : isDark
                                  ? AppColors.textSecondaryOnDark
                                  : AppColors.textSecondary,
                            ),
                          ),
                        ),
                      ),
                      const SizedBox(width: AppSpacing.md),
                      Expanded(
                        child: Text(
                          option,
                          style: AppTypography.body1.copyWith(
                            color: isDark
                                ? AppColors.textOnDark
                                : AppColors.textPrimary,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            );
          }).toList(),
        );

      case QuestionType.multiChoice:
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Padding(
              padding: const EdgeInsets.only(bottom: AppSpacing.sm),
              child: Text(
                _i18n(en: 'Select all that apply', zh: '选择所有正确答案'),
                style: AppTypography.label.copyWith(
                  color: isDark
                      ? AppColors.textSecondaryOnDark
                      : AppColors.textSecondary,
                ),
              ),
            ),
            ...question.options!.asMap().entries.map((entry) {
              final index = entry.key;
              final option = entry.value;
              final isSelected = _multiChoiceSelection.contains(index);
              return Padding(
                padding: const EdgeInsets.only(bottom: AppSpacing.md),
                child: GestureDetector(
                  onTap: () {
                    _audioService.playClick();
                    setState(() {
                      if (isSelected) {
                        _multiChoiceSelection.remove(index);
                      } else {
                        _multiChoiceSelection.add(index);
                      }
                    });
                  },
                  child: AnimatedContainer(
                    duration: const Duration(milliseconds: 150),
                    padding: const EdgeInsets.all(AppSpacing.md),
                    decoration: BoxDecoration(
                      color: isSelected
                          ? AppColors.primary.withValues(alpha: 0.08)
                          : isDark
                          ? AppColors.cardDark
                          : AppColors.surface,
                      borderRadius: AppRadius.borderRadiusXl,
                      border: Border.all(
                        color: isSelected
                            ? AppColors.primary
                            : isDark
                            ? AppColors.borderDark
                            : AppColors.border,
                        width: isSelected ? 2 : 1,
                      ),
                      boxShadow: isSelected ? AppShadows.sm : null,
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 32,
                          height: 32,
                          decoration: BoxDecoration(
                            color: isSelected
                                ? AppColors.primary
                                : isDark
                                ? AppColors.surfaceDark
                                : AppColors.surfaceVariant,
                            borderRadius: BorderRadius.circular(6),
                            border: isSelected
                                ? null
                                : Border.all(
                                    color: isDark
                                        ? AppColors.borderDark
                                        : AppColors.border,
                                  ),
                          ),
                          child: isSelected
                              ? const Icon(
                                  Icons.check,
                                  size: 18,
                                  color: Colors.white,
                                )
                              : null,
                        ),
                        const SizedBox(width: AppSpacing.md),
                        Expanded(
                          child: Text(
                            option,
                            style: AppTypography.body1.copyWith(
                              color: isDark
                                  ? AppColors.textOnDark
                                  : AppColors.textPrimary,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              );
            }),
          ],
        );

      case QuestionType.sorting:
        return ReorderableListView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: _sortingOrder.length,
          onReorder: (oldIndex, newIndex) {
            _audioService.playClick();
            setState(() {
              if (oldIndex < newIndex) newIndex -= 1;
              final item = _sortingOrder.removeAt(oldIndex);
              _sortingOrder.insert(newIndex, item);
            });
          },
          itemBuilder: (context, index) {
            final item = _sortingOrder[index];
            return Container(
              key: ValueKey(item),
              margin: const EdgeInsets.only(bottom: AppSpacing.sm),
              padding: const EdgeInsets.all(AppSpacing.md),
              decoration: BoxDecoration(
                color: isDark ? AppColors.cardDark : AppColors.surface,
                borderRadius: AppRadius.borderRadiusLg,
                border: Border.all(
                  color: isDark ? AppColors.borderDark : AppColors.border,
                ),
                boxShadow: isDark ? null : AppShadows.sm,
              ),
              child: Row(
                children: [
                  Icon(
                    Icons.drag_handle,
                    color: isDark
                        ? AppColors.textSecondaryOnDark
                        : AppColors.textSecondary,
                  ),
                  const SizedBox(width: AppSpacing.md),
                  Text(
                    item,
                    style: AppTypography.headline3.copyWith(
                      color: isDark
                          ? AppColors.textOnDark
                          : AppColors.textPrimary,
                    ),
                  ),
                ],
              ),
            );
          },
        );

      case QuestionType.input:
        return TextField(
          controller: _inputController,
          keyboardType: TextInputType.number,
          style: AppTypography.headline2.copyWith(
            color: isDark ? AppColors.textOnDark : AppColors.textPrimary,
          ),
          textAlign: TextAlign.center,
          decoration: InputDecoration(
            hintText: t.lessonEnterAnswer,
            hintStyle: AppTypography.headline2.copyWith(
              color: isDark
                  ? AppColors.textSecondaryOnDark
                  : AppColors.textDisabled,
            ),
            filled: true,
            fillColor: isDark ? AppColors.cardDark : AppColors.surface,
            border: OutlineInputBorder(
              borderRadius: AppRadius.borderRadiusXl,
              borderSide: BorderSide(
                color: isDark ? AppColors.borderDark : AppColors.border,
              ),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: AppRadius.borderRadiusXl,
              borderSide: const BorderSide(color: AppColors.primary, width: 2),
            ),
          ),
        );

      case QuestionType.matching:
        return _MatchingInteractionWidget(
          leftItems: question.matchingLeftItems!,
          rightItems: question.matchingRightItems!,
          matches: _matchingState,
          selectedLeft: _selectedLeftItem,
          isDark: isDark,
          onLeftTap: (item) {
            setState(() {
              _selectedLeftItem = _selectedLeftItem == item ? null : item;
            });
          },
          onRightTap: (item) {
            if (_selectedLeftItem == null) return;
            _audioService.playClick();
            setState(() {
              // Unlink right item if already matched
              _matchingState.removeWhere((_, v) => v == item);
              _matchingState[_selectedLeftItem!] = item;
              _selectedLeftItem = null;
            });
          },
          onClearPair: (leftItem) {
            setState(() {
              _matchingState.remove(leftItem);
            });
          },
        );

      case QuestionType.interactiveVisual:
        if (question.visualSpec != null) {
          return _ViewerInteractiveVisualCard(
            spec: question.visualSpec!,
            title: question.title,
          );
        }
        return const SizedBox.shrink();

      case QuestionType.info:
        if (question.isLast) {
          return Center(
            child: Container(
              width: 100,
              height: 100,
              decoration: BoxDecoration(
                color: AppColors.success.withValues(alpha: 0.1),
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.celebration,
                size: 48,
                color: AppColors.success,
              ),
            ),
          );
        }
        return const SizedBox.shrink();
    }
  }

  Widget _buildBottomBar(
    _QuestionData question,
    bool isDark,
    AppLocalizations t,
  ) {
    final isInfoPage = question.type == QuestionType.info ||
        question.type == QuestionType.interactiveVisual;
    final canSubmit =
        isInfoPage ||
        (question.type == QuestionType.choice && _selectedOption != null) ||
        (question.type == QuestionType.multiChoice &&
            _multiChoiceSelection.isNotEmpty) ||
        (question.type == QuestionType.input &&
            _inputController.text.isNotEmpty) ||
        question.type == QuestionType.sorting ||
        (question.type == QuestionType.matching &&
            _matchingState.length ==
                (question.matchingLeftItems?.length ?? 0));

    final label = _contentUnavailable
        ? t.lessonBack
        : isInfoPage
        ? (question.isLast ? t.lessonComplete : t.lessonContinue)
        : t.lessonSubmit;

    final hasHints =
        !isInfoPage &&
        question.hints != null &&
        question.hints!.isNotEmpty;
    final hintsExhausted = hasHints && _hintsUsed >= (question.hints?.length ?? 0);

    return Container(
      padding: const EdgeInsets.fromLTRB(
        AppSpacing.md,
        AppSpacing.sm,
        AppSpacing.md,
        AppSpacing.md,
      ),
      decoration: BoxDecoration(
        color: isDark ? AppColors.surfaceDark : AppColors.surface,
        boxShadow: [
          BoxShadow(
            color: Colors.black.withValues(alpha: 0.05),
            blurRadius: 10,
            offset: const Offset(0, -2),
          ),
        ],
      ),
      child: Row(
        children: [
          // Hint button
          if (hasHints) ...[
            Tooltip(
              message: hintsExhausted
                  ? (t.isZh ? '已无更多提示' : 'No more hints')
                  : (t.isZh
                        ? '显示提示 ($_hintsUsed/${question.hints!.length})'
                        : 'Show hint ($_hintsUsed/${question.hints!.length})'),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 200),
                decoration: BoxDecoration(
                  color: hintsExhausted
                      ? (isDark ? AppColors.cardDark : AppColors.surfaceVariant)
                      : const Color(0xFFFEF3C7),
                  borderRadius: AppRadius.borderRadiusFull,
                  border: Border.all(
                    color: hintsExhausted
                        ? AppColors.border
                        : const Color(0xFFF59E0B),
                  ),
                ),
                child: IconButton(
                  onPressed: hintsExhausted
                      ? null
                      : () {
                          setState(() {
                            _hintsUsed++;
                            _hintVisible = true;
                          });
                        },
                  icon: Text(
                    '💡',
                    style: TextStyle(
                      fontSize: 18,
                      color: hintsExhausted ? null : null,
                    ),
                  ),
                  constraints: const BoxConstraints(
                    minWidth: 44,
                    minHeight: 44,
                  ),
                ),
              ),
            ),
            const SizedBox(width: AppSpacing.sm),
          ],
          // Submit / Continue button
          Expanded(
            child: _Duo3DSubmitButton(
              onPressed: canSubmit
                  ? (_contentUnavailable
                        ? () => Navigator.pop(context)
                        : (isInfoPage ? _nextQuestion : _checkAnswer))
                  : null,
              label: label,
            ),
          ),
        ],
      ),
    );
  }

  void _showExitDialog(AppLocalizations t) {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(t.lessonExitTitle),
        content: Text(t.lessonExitBody),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(t.cancel),
          ),
          TextButton(
            onPressed: () {
              Navigator.pop(context);
              Navigator.pop(context);
            },
            child: Text(t.lessonExit, style: TextStyle(color: AppColors.error)),
          ),
        ],
      ),
    );
  }
}

// ── Duolingo-style 3D submit button ──────────────────────────────

class _Duo3DSubmitButton extends StatefulWidget {
  final VoidCallback? onPressed;
  final String label;

  const _Duo3DSubmitButton({required this.onPressed, required this.label});

  @override
  State<_Duo3DSubmitButton> createState() => _Duo3DSubmitButtonState();
}

class _Duo3DSubmitButtonState extends State<_Duo3DSubmitButton> {
  bool _isPressed = false;

  bool get _isEnabled => widget.onPressed != null;

  @override
  Widget build(BuildContext context) {
    final color = _isEnabled ? AppColors.primary : AppColors.border;
    final shadowColor = _isEnabled ? AppColors.buttonShadow : AppColors.border;

    return GestureDetector(
      onTapDown: _isEnabled ? (_) => setState(() => _isPressed = true) : null,
      onTapUp: _isEnabled
          ? (_) {
              setState(() => _isPressed = false);
              widget.onPressed!();
            }
          : null,
      onTapCancel: _isEnabled ? () => setState(() => _isPressed = false) : null,
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 80),
        padding: const EdgeInsets.symmetric(horizontal: 28, vertical: 16),
        margin: EdgeInsets.only(
          top: _isPressed ? 4 : 0,
          bottom: _isPressed ? 0 : 4,
        ),
        decoration: BoxDecoration(
          color: color,
          borderRadius: AppRadius.borderRadiusFull,
          border: Border(
            bottom: BorderSide(
              color: _isPressed ? color : shadowColor,
              width: _isPressed ? 0 : 4,
            ),
          ),
        ),
        child: Center(
          child: Text(
            widget.label,
            style: AppTypography.button.copyWith(
              color: _isEnabled ? Colors.white : AppColors.textDisabled,
            ),
          ),
        ),
      ),
    );
  }
}

// ── Data models ───────────────────────────────────────────────────

enum QuestionType { info, video, choice, multiChoice, input, sorting, matching, interactiveVisual }

class _QuestionData {
  final QuestionType type;
  final String title;
  final String content;
  final List<String>? options;
  final int? correctIndex;
  final String? correctAnswer;
  final List<String>? sortingItems;
  final List<String>? correctOrder;
  final String? successMsg;
  final String? failMsg;
  final bool isLast;
  // Matching
  final List<String>? matchingLeftItems;
  final List<String>? matchingRightItems;
  final Map<String, String>? matchingCorrectPairs;
  // Hints (shown on demand, up to 3)
  final List<String>? hints;
  // Image
  final String? imageUrl;
  // Interactive visual spec (JSON map)
  final Map<String, dynamic>? visualSpec;
  // Visibility gate: 'always' | 'afterPreviousCorrect'
  final String visibilityRule;
  // Multi-select: set of correct option indices
  final Set<int>? correctIndices;
  // Video URL (already converted to embeddable form)
  final String? videoUrl;

  _QuestionData({
    required this.type,
    required this.title,
    required this.content,
    this.options,
    this.correctIndex,
    this.correctAnswer,
    this.sortingItems,
    this.correctOrder,
    this.successMsg,
    this.failMsg,
    this.isLast = false,
    this.matchingLeftItems,
    this.matchingRightItems,
    this.matchingCorrectPairs,
    this.hints,
    this.imageUrl,
    this.visualSpec,
    this.visibilityRule = 'always',
    this.correctIndices,
    this.videoUrl,
  });
}

// ── Matching interaction widget ──────────────────────────────────

class _MatchingInteractionWidget extends StatelessWidget {
  final List<String> leftItems;
  final List<String> rightItems;
  final Map<String, String> matches; // left → right
  final String? selectedLeft;
  final bool isDark;
  final ValueChanged<String> onLeftTap;
  final ValueChanged<String> onRightTap;
  final ValueChanged<String> onClearPair;

  static const _pairColors = [
    Color(0xFF6366F1),
    Color(0xFF10B981),
    Color(0xFFF59E0B),
    Color(0xFFEF4444),
    Color(0xFF8B5CF6),
    Color(0xFF06B6D4),
  ];

  const _MatchingInteractionWidget({
    required this.leftItems,
    required this.rightItems,
    required this.matches,
    required this.selectedLeft,
    required this.isDark,
    required this.onLeftTap,
    required this.onRightTap,
    required this.onClearPair,
  });

  Color? _colorForLeftItem(String item) {
    final idx = matches.keys.toList().indexOf(item);
    if (idx < 0) return null;
    return _pairColors[idx % _pairColors.length];
  }

  Color? _colorForRightItem(String item) {
    final leftKey = matches.entries
        .where((e) => e.value == item)
        .map((e) => e.key)
        .firstOrNull;
    if (leftKey == null) return null;
    return _colorForLeftItem(leftKey);
  }

  @override
  Widget build(BuildContext context) {
    final surfaceColor = isDark ? AppColors.cardDark : AppColors.surface;
    final borderColor = isDark ? AppColors.borderDark : AppColors.border;

    Widget itemChip({
      required String text,
      required bool isSelected,
      required Color? matchColor,
      required VoidCallback onTap,
      bool isLeft = true,
    }) {
      return GestureDetector(
        onTap: onTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          margin: const EdgeInsets.only(bottom: 8),
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          decoration: BoxDecoration(
            color: isSelected
                ? AppColors.primary.withValues(alpha: 0.1)
                : matchColor != null
                ? matchColor.withValues(alpha: 0.08)
                : surfaceColor,
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: isSelected
                  ? AppColors.primary
                  : matchColor ?? borderColor,
              width: (isSelected || matchColor != null) ? 2 : 1,
            ),
            boxShadow: isSelected || matchColor != null
                ? [
                    BoxShadow(
                      color: (isSelected ? AppColors.primary : matchColor!)
                          .withValues(alpha: 0.15),
                      blurRadius: 6,
                      offset: const Offset(0, 2),
                    ),
                  ]
                : null,
          ),
          child: Row(
            children: [
              if (isLeft && matchColor != null) ...[
                Container(
                  width: 8,
                  height: 8,
                  decoration: BoxDecoration(
                    color: matchColor,
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: 6),
              ],
              Expanded(
                child: Text(
                  text,
                  style: AppTypography.body1.copyWith(
                    color: isDark ? AppColors.textOnDark : AppColors.textPrimary,
                    fontWeight: isSelected || matchColor != null
                        ? FontWeight.w600
                        : FontWeight.normal,
                  ),
                ),
              ),
              if (!isLeft && matchColor != null) ...[
                const SizedBox(width: 6),
                Container(
                  width: 8,
                  height: 8,
                  decoration: BoxDecoration(
                    color: matchColor,
                    shape: BoxShape.circle,
                  ),
                ),
              ],
            ],
          ),
        ),
      );
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // Instruction
        Padding(
          padding: const EdgeInsets.only(bottom: 12),
          child: Text(
            isDark
                ? 'Tap left item, then tap matching right item'
                : selectedLeft != null
                ? 'Now tap the matching right item →'
                : 'Tap a left item to begin matching',
            style: AppTypography.body2.copyWith(
              color: isDark
                  ? AppColors.textSecondaryOnDark
                  : AppColors.textSecondary,
              fontStyle: FontStyle.italic,
            ),
          ),
        ),
        // Two columns
        Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // Left column
            Expanded(
              child: Column(
                children: leftItems
                    .map(
                      (item) => itemChip(
                        text: item,
                        isSelected: selectedLeft == item,
                        matchColor: _colorForLeftItem(item),
                        isLeft: true,
                        onTap: () => onLeftTap(item),
                      ),
                    )
                    .toList(),
              ),
            ),
            const SizedBox(width: 12),
            // Right column
            Expanded(
              child: Column(
                children: rightItems
                    .map(
                      (item) => itemChip(
                        text: item,
                        isSelected: false,
                        matchColor: _colorForRightItem(item),
                        isLeft: false,
                        onTap: () => onRightTap(item),
                      ),
                    )
                    .toList(),
              ),
            ),
          ],
        ),
        // Current matches summary
        if (matches.isNotEmpty) ...[
          const SizedBox(height: 12),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: matches.entries.map((e) {
              final color = _colorForLeftItem(e.key) ?? AppColors.primary;
              return GestureDetector(
                onTap: () => onClearPair(e.key),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 8,
                    vertical: 4,
                  ),
                  decoration: BoxDecoration(
                    color: color.withValues(alpha: 0.1),
                    borderRadius: BorderRadius.circular(20),
                    border: Border.all(color: color.withValues(alpha: 0.4)),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Container(
                        width: 6,
                        height: 6,
                        decoration: BoxDecoration(
                          color: color,
                          shape: BoxShape.circle,
                        ),
                      ),
                      const SizedBox(width: 4),
                      Text(
                        '${e.key} → ${e.value}',
                        style: TextStyle(
                          fontSize: 11,
                          color: color,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                      const SizedBox(width: 4),
                      Icon(Icons.close, size: 12, color: color),
                    ],
                  ),
                ),
              );
            }).toList(),
          ),
        ],
      ],
    );
  }
}

// ── Interactive Visual Card (Viewer-side renderer) ────────────────

/// Lightweight viewer-side renderer for interactive-visual blocks.
/// Parses the VisualSimSpec JSON map and renders template scenes + controls.
class _ViewerInteractiveVisualCard extends StatefulWidget {
  final Map<String, dynamic> spec;
  final String title;

  const _ViewerInteractiveVisualCard({
    required this.spec,
    required this.title,
  });

  @override
  State<_ViewerInteractiveVisualCard> createState() =>
      _ViewerInteractiveVisualCardState();
}

class _ViewerInteractiveVisualCardState
    extends State<_ViewerInteractiveVisualCard> {
  late Map<String, dynamic> _state;
  int _stepIndex = 0;

  @override
  void initState() {
    super.initState();
    final initial = widget.spec['initialState'];
    _state = initial is Map ? Map<String, dynamic>.from(initial) : {};
  }

  void _handleAction(String action) {
    if (action == 'reset') {
      final initial = widget.spec['initialState'];
      setState(() {
        _state = initial is Map ? Map<String, dynamic>.from(initial) : {};
        _stepIndex = 0;
      });
    } else if (action == 'step') {
      _doStep();
    } else if (action == 'randomize') {
      _doRandomize();
    }
  }

  void _doStep() {
    final template = widget.spec['template'] as String? ?? '';
    if (template == 'sorting-bars') {
      _stepSortingBars();
    } else if (template == 'variable-binding-memory') {
      _stepVariableMemory();
    } else {
      setState(() => _stepIndex++);
    }
  }

  void _stepSortingBars() {
    final vals = List<int>.from(_state['values'] as List? ?? []);
    final n = vals.length;
    int si = _state['stepIndex'] as int? ?? 0;
    final stepsPerPass = n - 1;
    final pass = si ~/ stepsPerPass;
    final idx = si % stepsPerPass;
    if (pass >= n - 1) {
      setState(() {
        _state['comparing'] = <int>[];
        _state['swapped'] = <int>[];
        _state['sorted'] = List.generate(n, (i) => i);
      });
      return;
    }
    final comparing = [idx, idx + 1];
    List<int> swapped = [];
    if (vals[idx] > vals[idx + 1]) {
      final tmp = vals[idx];
      vals[idx] = vals[idx + 1];
      vals[idx + 1] = tmp;
      swapped = [idx, idx + 1];
    }
    setState(() {
      _state['values'] = vals;
      _state['stepIndex'] = si + 1;
      _state['comparing'] = comparing;
      _state['swapped'] = swapped;
      _state['sorted'] = List.generate(pass, (i) => n - 1 - i);
    });
  }

  void _stepVariableMemory() {
    final steps = (widget.spec['scene']?['steps'] as List?) ?? [];
    if (_stepIndex >= steps.length) return;
    final step = Map<String, dynamic>.from(steps[_stepIndex] as Map);
    final vars = List<Map>.from(_state['variables'] as List? ?? []);
    final mem = List<Map>.from(_state['memory'] as List? ?? []);
    final varName = step['varName'] as String?;
    final value = step['value'];
    final address = step['address'] as String?;
    if (varName != null) {
      vars.removeWhere((v) => v['name'] == varName);
      vars.add({
        'name': varName,
        'value': value,
        'address': address,
        'active': true,
      });
      mem.removeWhere((m) => m['address'] == address);
      mem.add({'address': address, 'value': value, 'active': true});
    }
    setState(() {
      _state['variables'] = vars;
      _state['memory'] = mem;
      _state['stepIndex'] = _stepIndex + 1;
      _stepIndex++;
    });
  }

  void _doRandomize() {
    final rng = math.Random();
    final n = (widget.spec['scene']?['barCount'] as int?) ?? 9;
    setState(() {
      final initial = widget.spec['initialState'];
      _state = initial is Map ? Map<String, dynamic>.from(initial) : {};
      _state['values'] = List.generate(n, (_) => rng.nextInt(n) + 1);
      _stepIndex = 0;
    });
  }

  @override
  Widget build(BuildContext context) {
    final template = widget.spec['template'] as String? ?? 'generic';
    final controls = (widget.spec['controls'] as List? ?? [])
        .whereType<Map>()
        .map((c) => Map<String, dynamic>.from(c))
        .toList();
    final formulas = (widget.spec['formulas'] as List? ?? [])
        .whereType<Map>()
        .map((f) => Map<String, dynamic>.from(f))
        .toList();
    final tone = widget.spec['themeTone'] as String? ?? 'light-science';
    final isDark = tone != 'light-science';
    final bg = isDark ? const Color(0xFF0D1117) : const Color(0xFFF7F9FC);
    final borderColor =
        isDark ? const Color(0xFF30363D) : const Color(0xFFD0D7DE);
    final textColor =
        isDark ? const Color(0xFFE6EDF3) : const Color(0xFF1F2328);
    final labelColor =
        isDark ? const Color(0xFF8B949E) : const Color(0xFF57606A);

    return Container(
      margin: const EdgeInsets.symmetric(vertical: 8),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: borderColor),
      ),
      clipBehavior: Clip.antiAlias,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Formula bar
          if (formulas.isNotEmpty) _buildFormulaBar(formulas, textColor),
          // Scene
          SizedBox(
            height: 200,
            child: _buildScene(template, isDark),
          ),
          // Controls
          if (controls.isNotEmpty)
            _buildControlBar(controls, isDark, textColor, labelColor),
        ],
      ),
    );
  }

  Widget _buildFormulaBar(
    List<Map<String, dynamic>> formulas,
    Color textColor,
  ) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
      child: Wrap(
        spacing: 16,
        children:
            formulas
                .map(
                  (f) => Text(
                    f['expression'] as String? ?? '',
                    style: TextStyle(
                      fontFamily: 'monospace',
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                      color: textColor,
                    ),
                  ),
                )
                .toList(),
      ),
    );
  }

  Widget _buildScene(String template, bool isDark) {
    final bg = isDark ? const Color(0xFF0D1117) : const Color(0xFFF0F6FF);
    switch (template) {
      case 'sorting-bars':
        return Container(
          color: bg,
          padding: const EdgeInsets.all(8),
          child: CustomPaint(
            painter: _ViewerSortingBarsPainter(
              values:
                  (_state['values'] as List?)?.cast<int>() ??
                  [5, 3, 8, 1, 9, 2, 7, 4, 6],
              comparing: (_state['comparing'] as List?)?.cast<int>() ?? [],
              swapped: (_state['swapped'] as List?)?.cast<int>() ?? [],
              sorted: (_state['sorted'] as List?)?.cast<int>() ?? [],
              isDark: isDark,
            ),
          ),
        );
      case 'variable-binding-memory':
        final vars = (_state['variables'] as List?)?.cast<Map>() ?? [];
        final mem = (_state['memory'] as List?)?.cast<Map>() ?? [];
        final stepIdx = _state['stepIndex'] as int? ?? 0;
        final steps = (widget.spec['scene']?['steps'] as List?) ?? [];
        return Container(
          color: bg,
          padding: const EdgeInsets.all(12),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (steps.isNotEmpty && stepIdx < steps.length)
                Text(
                  (steps[stepIdx] as Map?)?.values.first?.toString() ?? '',
                  style: TextStyle(
                    fontFamily: 'monospace',
                    fontSize: 12,
                    color:
                        isDark
                            ? const Color(0xFF58A6FF)
                            : const Color(0xFF0969DA),
                  ),
                ),
              const SizedBox(height: 8),
              Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Variables',
                          style: TextStyle(
                            fontSize: 11,
                            color:
                                isDark
                                    ? const Color(0xFF8B949E)
                                    : const Color(0xFF57606A),
                          ),
                        ),
                        ...vars.map(
                          (v) => _VarSlot(
                            label: '${v['name']}',
                            value: '${v['value']}',
                            isDark: isDark,
                            active: v['active'] as bool? ?? false,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Memory',
                          style: TextStyle(
                            fontSize: 11,
                            color:
                                isDark
                                    ? const Color(0xFF8B949E)
                                    : const Color(0xFF57606A),
                          ),
                        ),
                        ...mem.map(
                          (m) => _VarSlot(
                            label: '${m['address']}',
                            value: '${m['value']}',
                            isDark: isDark,
                            active: m['active'] as bool? ?? false,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ],
          ),
        );
      default:
        // Generic: show state key-values
        return Container(
          color: bg,
          padding: const EdgeInsets.all(12),
          child:
              _state.isEmpty
                  ? Center(
                    child: Text(
                      widget.title,
                      style: TextStyle(
                        fontSize: 15,
                        color:
                            isDark
                                ? const Color(0xFFE6EDF3)
                                : const Color(0xFF1F2328),
                      ),
                    ),
                  )
                  : Wrap(
                    spacing: 16,
                    runSpacing: 8,
                    children:
                        _state.entries
                            .map(
                              (e) => Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    e.key,
                                    style: TextStyle(
                                      fontSize: 10,
                                      color:
                                          isDark
                                              ? const Color(0xFF8B949E)
                                              : const Color(0xFF57606A),
                                    ),
                                  ),
                                  Text(
                                    e.value.toString(),
                                    style: TextStyle(
                                      fontSize: 16,
                                      fontWeight: FontWeight.w700,
                                      color:
                                          isDark
                                              ? const Color(0xFF58A6FF)
                                              : const Color(0xFF0969DA),
                                    ),
                                  ),
                                ],
                              ),
                            )
                            .toList(),
                  ),
        );
    }
  }

  Widget _buildControlBar(
    List<Map<String, dynamic>> controls,
    bool isDark,
    Color textColor,
    Color labelColor,
  ) {
    final panelBg =
        isDark ? const Color(0xFF161B22) : const Color(0xFFEFF3F8);
    return Container(
      color: panelBg,
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
      child: Column(
        children: [
          // Sliders
          ...controls.where((c) => c['type'] == 'slider').map((ctrl) {
            final key = ctrl['stateKey'] as String? ?? '';
            final rawVal = _state[key];
            final current =
                rawVal is num
                    ? rawVal.toDouble()
                    : (ctrl['defaultValue'] is num
                        ? (ctrl['defaultValue'] as num).toDouble()
                        : (ctrl['min'] as num? ?? 0).toDouble());
            final min = (ctrl['min'] as num?)?.toDouble() ?? 0;
            final max = (ctrl['max'] as num?)?.toDouble() ?? 100;
            final unit = ctrl['unit'] as String? ?? '';
            final label = ctrl['label'] as String? ?? '';
            return Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Row(
                  children: [
                    Text(
                      label,
                      style: TextStyle(fontSize: 11, color: textColor),
                    ),
                    const Spacer(),
                    Text(
                      '${current.toStringAsFixed(1)}$unit',
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                        color: textColor,
                      ),
                    ),
                  ],
                ),
                Slider(
                  value: current.clamp(min, max),
                  min: min,
                  max: max,
                  onChanged: (v) => setState(() => _state[key] = v),
                  activeColor:
                      isDark
                          ? const Color(0xFF58A6FF)
                          : const Color(0xFF0969DA),
                ),
              ],
            );
          }),
          // Buttons
          if (controls.any((c) => c['type'] == 'button'))
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children:
                  controls.where((c) => c['type'] == 'button').map((ctrl) {
                    final action = ctrl['action'] as String? ?? '';
                    final label = ctrl['label'] as String? ?? '';
                    return Padding(
                      padding: const EdgeInsets.only(right: 6),
                      child: OutlinedButton(
                        onPressed: () => _handleAction(action),
                        style: OutlinedButton.styleFrom(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 10,
                            vertical: 6,
                          ),
                          side: BorderSide(
                            color:
                                isDark
                                    ? const Color(0xFF30363D)
                                    : const Color(0xFFCFD8DC),
                          ),
                          foregroundColor: textColor,
                          textStyle: const TextStyle(fontSize: 12),
                        ),
                        child: Text(label),
                      ),
                    );
                  }).toList(),
            ),
        ],
      ),
    );
  }
}

