                        ...vars.map(
                          (v) => _VarSlot(
                            label: '${v['name']}',
                            value: '${v['value']}',
                            isDark: isDark,
                            active: v['active'] as bool? ?? false,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Memory',
                          style: TextStyle(
                            fontSize: 11,
                            color:
                                isDark
                                    ? const Color(0xFF8B949E)
                                    : const Color(0xFF57606A),
                          ),
                        ),
                        ...mem.map(
                          (m) => _VarSlot(
                            label: '${m['address']}',
                            value: '${m['value']}',
                            isDark: isDark,
                            active: m['active'] as bool? ?? false,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ],
          ),
        );
      default:
        // Generic: show state key-values
        return Container(
          color: bg,
          padding: const EdgeInsets.all(12),
          child:
              _state.isEmpty
                  ? Center(
                    child: Text(
                      widget.title,
                      style: TextStyle(
                        fontSize: 15,
                        color:
                            isDark
                                ? const Color(0xFFE6EDF3)
                                : const Color(0xFF1F2328),
