    18→
    19→final _routerRefresh = Listenable.merge([
    20→  _GoRouterRefreshStream(SupabaseService.authStateChanges),
    21→  builderAccessNotifier,
    22→]);
    23→
    24→final appRouter = GoRouter(
    25→  initialLocation: '/',
    26→  refreshListenable: _routerRefresh,
    27→  redirect: (context, state) {
    28→    final loggedIn = SupabaseService.isLoggedIn;
    29→    final location = state.matchedLocation;
    30→    final access = builderAccessNotifier.state;
    31→
    32→    const protectedRoutes = {'/dashboard', '/builder'};
    33→    final isProtected = protectedRoutes.contains(location);
    34→
    35→    // Don't redirect away from the callback screen — let it process first
    36→    if (location == '/auth/callback') return null;
    37→
    38→    // Not logged in → bounce from protected routes
    39→    if (!loggedIn && isProtected) {
    40→      SupabaseService.pendingRedirect = state.uri.toString();
    41→      return '/';
    42→    }
    43→
    44→    // Session restored but role check still in progress →
    45→    // hold the user on landing (which shows a loading screen) instead of
    46→    // letting them through to a protected route.
    47→    if (loggedIn && access == AccessState.checking) {
    48→      return isProtected ? '/' : null;
    49→    }
    50→
    51→    // Role check failed → stay on landing; the notifier already signed them out
    52→    if (access == AccessState.denied && isProtected) {
    53→      return '/';
    54→    }
    55→
    56→    // Logged in + role verified → advance from landing/login to dashboard
    57→    if (loggedIn &&
    58→        access == AccessState.allowed &&
    59→        (location == '/' || location == '/login' || location == '/register')) {
    60→      return '/dashboard';
    61→    }
    62→
    63→    return null;
    64→  },
    65→  routes: [
    66→    GoRoute(
    67→      path: '/',
    68→      name: 'landing',
    69→      builder: (context, state) => const LandingScreen(),
    70→    ),
    71→    GoRoute(
    72→      path: '/login',
    73→      name: 'login',
    74→      builder: (context, state) => const LoginScreen(),
    75→    ),
    76→    GoRoute(
    77→      path: '/register',
    78→      name: 'register',
    79→      builder: (context, state) => const RegisterScreen(),
    80→    ),
    81→    GoRoute(
    82→      path: '/dashboard',
    83→      name: 'dashboard',
    84→      builder: (context, state) => const DashboardScreen(),
    85→    ),
    86→    GoRoute(
    87→      path: '/builder',
    88→      name: 'builder',
    89→      builder: (context, state) {
    90→        final courseId = state.uri.queryParameters['courseId'];
    91→        final addLesson = state.uri.queryParameters['addLesson'] == '1';
    92→        final draftId = state.uri.queryParameters['draftId'];
    93→        final lessonIndex = int.tryParse(
    94→          state.uri.queryParameters['lessonIndex'] ?? '',
    95→        );
    96→        final lessonTitle = state.uri.queryParameters['lessonTitle'];
    97→        final courseTitle = state.uri.queryParameters['courseTitle'];
    98→        return BuilderScreen(
    99→          courseId: courseId,
