   101→          draftId: draftId,
   102→          lessonIndex: lessonIndex,
   103→          lessonTitle: lessonTitle,
   104→          parentCourseTitle: courseTitle,
   105→        );
   106→      },
   107→    ),
   108→    GoRoute(
   109→      path: '/auth/callback',
   110→      name: 'authCallback',
   111→      builder: (context, state) => const AuthCallbackScreen(),
   112→    ),
   113→    GoRoute(
   114→      path: '/viewer',
