   116→      builder: (context, state) {
   117→        final courseId = state.uri.queryParameters['courseId'];
   118→        final addLesson = state.uri.queryParameters['addLesson'] == '1';
   119→        final draftId = state.uri.queryParameters['draftId'];
   120→        final lessonIndex = int.tryParse(
   121→          state.uri.queryParameters['lessonIndex'] ??
   122→              state.uri.queryParameters['pageIndex'] ??
   123→              '',
   124→        );
   125→        final singlePage = state.uri.queryParameters['singlePage'] == '1';
   126→        return ViewerScreen(
   127→          courseId: courseId,
   128→          addLesson: addLesson,
   129→          draftId: draftId,
   130→          lessonIndex: lessonIndex,
   131→          singlePage: singlePage,
   132→        );
   133→      },
   134→    ),
