    11→/// Supabase service - handles auth, course storage, publishing, etc.
    12→class SupabaseService {
    13→  SupabaseService._();
    14→
    15→  static SupabaseClient get client => Supabase.instance.client;
    16→  static const Duration _authTimeout = Duration(seconds: 45);
    17→  static const Set<String> _builderRoles = {'author', 'admin'};
    18→  static const Set<String> _builderAccessEmailAllowlist = {
    19→    'kieransweg@gmail.com',
    20→  };
    21→  static const String _builderAccessDeniedMessage =
    22→      'This account does not have Builder access. '
    23→      'Please use an author/admin account.';
    24→
    25→  /// Current user
    26→  static User? get currentUser => client.auth.currentUser;
    27→
    28→  /// Is logged in
    29→  static bool get isLoggedIn => currentUser != null;
    30→
    31→  /// Auth state changes
    32→  static Stream<AuthState> get authStateChanges =>
    33→      client.auth.onAuthStateChange;
    34→
    35→  static String get builderAccessDeniedMessage => _builderAccessDeniedMessage;
    36→
    37→  // ==================== Auth ====================
    38→
    39→  /// Sign up with email
    40→  static Future<AuthResult> signUp({
    41→    required String email,
    42→    required String password,
    43→    String? displayName,
    44→  }) async {
    45→    try {
    46→      final response = await _withAuthTimeout(
    47→        client.auth.signUp(
    48→          email: email,
    49→          password: password,
    50→          data: displayName != null ? {'name': displayName} : null,
    51→        ),
    52→        operation: 'Sign up',
    53→      );
    54→
    55→      if (response.user != null) {
    56→        // Do not block account creation on profile sync.
    57→        unawaited(_ensureAllowlistedUserRole());
    58→        return AuthResult(success: true, message: 'Sign up successful');
    59→      } else {
    60→        return const AuthResult(success: false, message: 'Sign up failed');
    61→      }
    62→    } on AuthException catch (e) {
    63→      return AuthResult(
    64→        success: false,
    65→        message: _translateAuthError(e.message),
    66→      );
    67→    } catch (e) {
    68→      return AuthResult(success: false, message: _translateAuthError('$e'));
    69→    }
    70→  }
    71→
    72→  /// Check if an email is registered
    73→  static Future<bool> isEmailRegistered(String email) async {
    74→    try {
    75→      // Attempt to send a password recovery to check existence.
    76→      // Supabase doesn't expose a direct "user exists" API for anon,
    77→      // so we query the profiles table if accessible, otherwise fall back.
    78→      final response = await client
    79→          .from('profiles')
    80→          .select('id')
    81→          .eq('email', email)
    82→          .maybeSingle();
    83→      return response != null;
    84→    } catch (_) {
    85→      // If profiles table doesn't have email or RLS blocks it,
    86→      // we can't pre-check — just let signIn handle errors.
    87→      return true; // assume exists, let sign-in decide
    88→    }
    89→  }
    90→
    91→  /// Sign in with email
    92→  static Future<AuthResult> signIn({
    93→    required String email,
    94→    required String password,
    95→  }) async {
    96→    const maxAttempts = 3;
    97→    for (var attempt = 0; attempt < maxAttempts; attempt++) {
    98→      try {
    99→        final response = await _withAuthTimeout(
   100→          client.auth.signInWithPassword(email: email, password: password),
   101→          operation: 'Sign in',
   102→        );
   103→
   104→        if (response.user != null) {
   105→          // Allowlisted Builder accounts should not block on profile-role sync.
   106→          if (_isBuilderAllowlistedEmail(response.user?.email ?? email)) {
   107→            unawaited(_ensureAllowlistedUserRole());
   108→            return const AuthResult(success: true, message: 'Signed in');
   109→          }
   110→
   111→          final hasAccess = await _withAuthTimeout(
   112→            ensureBuilderAccess(signOutIfDenied: true),
   113→            operation: 'Access check',
   114→          );
   115→          if (!hasAccess) {
   116→            return const AuthResult(
   117→              success: false,
   118→              message: _builderAccessDeniedMessage,
   119→            );
   120→          }
   121→          return AuthResult(success: true, message: 'Signed in');
   122→        } else {
   123→          return const AuthResult(success: false, message: 'Sign in failed');
   124→        }
   125→      } on AuthException catch (e) {
   126→        if (_isRetryableAuthTimeout(e.message) && attempt < maxAttempts - 1) {
   127→          await Future<void>.delayed(_retryDelayForAttempt(attempt));
   128→          continue;
   129→        }
   130→        return AuthResult(
   131→          success: false,
   132→          message: _translateAuthError(e.message),
   133→          isUserNotFound: e.message.contains('Invalid login credentials'),
   134→        );
   135→      } catch (e) {
   136→        final errorText = e.toString();
   137→        if (_isRetryableAuthTimeout(errorText) && attempt < maxAttempts - 1) {
   138→          await Future<void>.delayed(_retryDelayForAttempt(attempt));
   139→          continue;
   140→        }
   141→        return AuthResult(
   142→          success: false,
   143→          message: _translateAuthError(errorText),
   144→        );
   145→      }
   146→    }
   147→
   148→    return const AuthResult(success: false, message: 'Sign in failed');
   149→  }
