    29→  /// Ensure we still have an authenticated user.
    30→  /// Attempts a session refresh when [currentUser] is null but a session exists.
    31→  static Future<bool> ensureAuthenticated() async {
    32→    final user = currentUser;
    33→    if (user != null) {
    34→      _lastOperationError = null;
