    36→    }
    37→
    38→    try {
    39→      final session = client.auth.currentSession;
    40→      final refreshToken = session?.refreshToken;
    41→      if (refreshToken != null && refreshToken.isNotEmpty) {
    42→        final refreshed = await client.auth.refreshSession(refreshToken);
    43→        if (refreshed.session?.user != null || currentUser != null) {
    44→          _lastOperationError = null;
