    66→    for (var attempt = 0; attempt < maxAttempts; attempt++) {
    67→      try {
    68→        final response = await _withAuthTimeout(
    69→          client.auth.signUp(
    70→            email: email,
    71→            password: password,
    72→            data: displayName != null ? {'name': displayName} : null,
    73→          ),
    74→          operation: 'Sign up',
    75→        );
    76→
    77→        if (response.user != null) {
    78→          return AuthResult(success: true, message: 'Sign up successful');
    79→        } else {
    80→          return const AuthResult(success: false, message: 'Sign up failed');
    81→        }
    82→      } on AuthException catch (e) {
    83→        if (_isRetryableAuthTimeout(e.message) && attempt < maxAttempts - 1) {
    84→          await Future<void>.delayed(_retryDelayForAttempt(attempt));
    85→          continue;
    86→        }
    87→        return AuthResult(
    88→          success: false,
    89→          message: _translateAuthError(e.message),
    90→        );
    91→      } catch (e) {
    92→        final errorText = e.toString();
    93→        if (_isRetryableAuthTimeout(errorText) && attempt < maxAttempts - 1) {
    94→          await Future<void>.delayed(_retryDelayForAttempt(attempt));
    95→          continue;
    96→        }
    97→        return AuthResult(success: false, message: 'Sign up failed: $e');
    98→      }
    99→    }
   100→    return const AuthResult(success: false, message: 'Sign up failed');
