   107→  }) async {
   108→    const maxAttempts = 3;
   109→    for (var attempt = 0; attempt < maxAttempts; attempt++) {
   110→      try {
   111→        final response = await _withAuthTimeout(
   112→          client.auth.signInWithPassword(email: email, password: password),
   113→          operation: 'Sign in',
   114→        );
   115→
   116→        if (response.user != null) {
   117→          return AuthResult(success: true, message: 'Signed in');
   118→        } else {
   119→          return const AuthResult(success: false, message: 'Sign in failed');
