     6→// ── Key normalisation ─────────────────────────────────────────────────────────
     7→// Builder stores content JSON in the database.  We output snake_case so that
     8→// Viewer (and any future API consumer) can use a single, consistent key format.
     9→// Builder's own fromJson() methods accept BOTH camelCase (legacy DB rows) and
    10→// snake_case (new rows) so old course data continues to load correctly.
    11→
    12→String _camelToSnake(String key) =>
    13→    key.replaceAllMapped(RegExp(r'([A-Z])'), (m) => '_${m.group(0)!.toLowerCase()}');
    14→
    15→String _snakeToCamel(String key) =>
    16→    key.replaceAllMapped(RegExp(r'_([a-z])'), (m) => m.group(1)!.toUpperCase());
    17→
    18→Map<String, dynamic> _normalizeToCamelCase(Map<String, dynamic> map) {
    19→  return map.map((key, value) {
    20→    final camelKey = _snakeToCamel(key);
    21→    if (value is Map<String, dynamic>) {
    22→      return MapEntry(camelKey, _normalizeToCamelCase(value));
    23→    } else if (value is List) {
    24→      return MapEntry(camelKey, _normalizeListToCamelCase(value));
    25→    }
    26→    return MapEntry(camelKey, value);
    27→  });
    28→}
    29→
    30→List<dynamic> _normalizeListToCamelCase(List<dynamic> list) {
    31→  return list.map((item) {
    32→    if (item is Map<String, dynamic>) return _normalizeToCamelCase(item);
    33→    if (item is List) return _normalizeListToCamelCase(item);
    34→    return item;
    35→  }).toList();
    36→}
    37→
    38→Map<String, dynamic> _normalizeToSnakeCase(Map<String, dynamic> map) {
    39→  return map.map((key, value) {
    40→    final snakeKey = _camelToSnake(key);
    41→    if (value is Map<String, dynamic>) {
    42→      return MapEntry(snakeKey, _normalizeToSnakeCase(value));
    43→    } else if (value is List) {
    44→      return MapEntry(snakeKey, _normalizeListToSnakeCase(value));
    45→    }
    46→    return MapEntry(snakeKey, value);
    47→  });
    48→}
    49→
    50→List<dynamic> _normalizeListToSnakeCase(List<dynamic> list) {
    51→  return list.map((item) {
    52→    if (item is Map<String, dynamic>) return _normalizeToSnakeCase(item);
    53→    if (item is List) return _normalizeListToSnakeCase(item);
    54→    return item;
    55→  }).toList();
    56→}
